(window.MUSEUM_READ_T = window.MUSEUM_READ_T || {})["hi"] = {"ui":{"lead":"खेल कैसे मिले, भुलाए गए, पढ़े गए और बदले? {n} कहानियाँ पढ़ें और अंत की प्रश्नोत्तरी के सभी सवाल सही करें — एक मुहर मिलेगी।","card":"मुहर कार्ड","cardN":"{of} में से {n} मिलीं","cardAll":"सब मिल गईं!","no":"कहानी {n}","mins":"{n} मिनट","stamped":"मुहर लगी","back":"सभी कहानियाँ","quiz":"छोटी प्रश्नोत्तरी","links":"देखें और खेलें","game":"खेल","exhibit":"संग्रह","art":"चित्र","room":"कक्ष","room_chance":"संयोग","qn":"प्रश्न {n} / {of}","right":"सही!","wrong":"नहीं — सही उत्तर पर निशान लगा दिया है।","got":"मुहर लग गई!","again":"सब सही!","gotSub":"यह आपके मुहर कार्ड पर दर्ज है।","missed":"{n} गलत","retrySub":"मुहर के लिए सभी सवाल सही करें। कहानी फिर से पढ़ें और दोबारा कोशिश करें।","retry":"फिर कोशिश करें","room_paint":"कला में","room_map":"नक्शा","kfH":"मुख्य बातें","tlH":"समय‑रेखा","refH":"स्रोत और आगे पढ़ें"},"ex":{"ur":"उर का शाही खेल‑बोर्ड","liubo":"लिउबो बोर्ड और गोटियाँ","pyrgus":"रोमन पासा‑मीनार","sugoroku":"शोसोइन का सुगोरोकु बोर्ड","nishapur":"निशापुर का शतरंज","lewis":"लुईस के शतरंज मोहरे","senet":"तूतनख़ामुन का सेनेट बक्सा","ballinderry":"बैलिंडेरी का खेल‑बोर्ड","goose":"शतरंज और बत्तख़ के खेल का बोर्ड","kofukuji":"कोफ़ुकु‑जी से निकले शोगी मोहरे","shosoin":"शोसोइन का गो बोर्ड"},"paint":{"liubo":"लिउबो खेलती दो आकृतियाँ","sugoroku":"सुगोरोकु खेलती दो लड़कियाँ","shahnama":"बुज़ुर्गमेहर शतरंज का रहस्य खोलते हैं","nefertari":"सेनेट खेलती रानी नेफ़रतारी","chaupar":"चौपड़ खेलते शिव और पार्वती","shogi":"शोगी खेलता युवा जोड़ा","hydria":"बोर्ड खेल खेलते अकिलीज़ और अयाक्स (जल‑कलश)","eakins":"शतरंज के खिलाड़ी","weiqi":"वेइची खेलते अमरों वाली थाली","webb":"बैकगैमन खेलते लोग (अलमारी)","liberale":"शतरंज खेलते लोग"},"ur":{"title":"4500 साल पुराने खेल के नियम फिर कैसे मिले","lead":"उर की शाही कब्रों से निकले बोर्ड के साथ नियम नहीं थे। सुराग दो हज़ार साल बाद लिखी मिट्टी की एक पट्टिका में था।","s":["1920 के दशक में लियोनार्ड वूली ने दक्षिणी इराक़ के उर में शाही कब्रें खोदीं और सीप तथा लाजवर्द से जड़ा बीस खानों वाला एक बोर्ड पाया, जो लगभग 2600–2400 ईसा पूर्व का है। ऐसे ही बोर्ड पूरे मध्य‑पूर्व में मिले हैं, यानी यह खेल लंबे समय तक दूर‑दूर तक खेला गया।","पर इनके साथ खेलने का तरीका बताने वाला कुछ नहीं मिला। बोर्ड, गोटियाँ और पासे थे — पर नियम नहीं: पुराने खेलों की आम समस्या।","सुराग ब्रिटिश म्यूज़ियम के भंडार में था: कीलाक्षर लिपि की एक पट्टिका, जिसे 177/176 ईसा पूर्व में बेबीलोन के लिपिक इत्ती‑मर्दुक‑बलातु ने इद्दिन‑बेल नाम के व्यक्ति की पट्टिका से उतारा था। यह बोर्ड के दो हज़ार साल से भी ज़्यादा बाद लिखी गई।","1980 के दशक की शुरुआत में ब्रिटिश म्यूज़ियम के इरविंग फ़िंकेल ने पहचाना कि यह पट्टिका उसी बीस खानों वाले खेल के बारे में है। उसके पीछे बोर्ड का चित्र है, और खानों पर रुकने के शुभ‑अशुभ फल लिखे हैं। पट्टिका और बोर्ड की बनावट से फ़िंकेल ने दो खिलाड़ियों की दौड़ वाला खेल फिर से गढ़ा।","उनका पुनर्निर्मित खेल आज दुनिया भर में खेला जाता है। उर के लोग ठीक ऐसे ही खेलते थे या नहीं, कोई नहीं कह सकता। फिर भी दक्षिण भारत के कोच्चि में 1950 के दशक तक एक मिलता‑जुलता खेल खेला जाता था — इस खेल की लंबी उम्र का संकेत।"],"quiz":[["नियम बताने वाली पट्टिका कब लिखी गई?","दूसरी सदी ईसा पूर्व में, बोर्ड के 2000 से ज़्यादा साल बाद","लगभग 2600 ईसा पूर्व, बोर्ड के साथ ही","मध्यकाल (12वीं सदी) में","19वीं सदी में"],["पट्टिका पढ़कर नियम किसने फिर से गढ़े?","इरविंग फ़िंकेल","हॉवर्ड कार्टर","शाम्पोलियों","आर्थर इवांस"],["पट्टिका में खानों पर रुकने के बारे में क्या लिखा है?","शुभ‑अशुभ फल","राजाओं के नाम","कर की रकम","सिर्फ़ तारों के नाम"]],"kf":["बोर्ड लगभग 2600–2400 ई.पू. के हैं, दक्षिणी इराक़ में उर के शाही मक़बरों से","नियम 2000 से ज़्यादा साल बाद लिखी मिट्टी की पटिया से दोबारा बनाए गए","20 ख़ाने, हर ओर सात गोटियाँ, चार‑मुखी पासे"],"more":[{"h":"शाही मक़बरे और \"शाही खेल\"","p":["वूली को उर के शाही क़ब्रिस्तान में बीस ख़ानों वाला एक नहीं, कई बोर्ड मिले। सबसे मशहूर बोर्ड, जो अब ब्रिटिश संग्रहालय में है, लकड़ी पर सीप, लाल चूना‑पत्थर और लाजवर्द जड़कर बना है — \"उर का शाही खेल\" नाम यहीं से आया।","पर यह सिर्फ़ राजाओं का खेल नहीं था। ऐसे ही बोर्ड मेसोपोटामिया से मिस्र और पूर्वी भूमध्यसागर तक मिले हैं, और एक असीरियाई महल में तो फाटक की रखवाली करने वाली मानव‑सिर वाली पंखदार बैल‑मूर्ति के आधार पर भी एक बोर्ड खुरचा मिला — शायद पहरेदारों ने बनाया।"],"cap":["ब्रिटिश संग्रहालय का \"उर का शाही खेल\" — संग्रह कक्ष में इसे 3D में घुमाकर देखें"]},{"h":"बोर्ड की बनावट","p":["बीस ख़ाने बारह (3×4) और छह (3×2) ख़ानों के दो हिस्सों से बने हैं, जिन्हें दो ख़ानों का पतला \"पुल\" जोड़ता है। पाँच ख़ानों पर फूल (रोज़ेट) बना है; पुनर्निर्मित नियमों में वहाँ रुकने पर एक और फेंक मिलती है और वहाँ गोटी मारी नहीं जा सकती।","पासे चतुष्फलक हैं, जिनके चार में से दो कोनों पर निशान हैं। चार पासे फेंककर जितने निशान ऊपर आएँ उतना चलते हैं: 0 से 4। सबसे ज़्यादा 2 आता है (16 में 6 बार); 0 और 4 सिर्फ़ 16 में एक बार। संग्रहालय के \"संयोग\" कक्ष में आप इन्हें फेंक सकते हैं।"],"cap":["बीस ख़ाने और पाँच रोज़ेट। हरे अंक एक खिलाड़ी का रास्ता ख़ाना‑दर‑ख़ाना दिखाते हैं (पुनर्निर्मित नियम)","चार चतुष्फलक पासे कैसे गिरते हैं (16 बराबर संभावनाओं में से)"]},{"h":"पटिया क्या कहती है","p":["पटिया के सामने खेल का विवरण है और पीछे बोर्ड का चित्र, जिसके ख़ानों में राशियों के चिह्न हैं। ख़ानों से जुड़े वाक्य भविष्यवाणी जैसे हैं — \"तुम्हें एक दोस्त मिलेगा\", \"तुम बढ़िया बियर पियोगे\" — यानी खेल क़िस्मत से जुड़ा था।","पर पटिया का कुछ हिस्सा टूटा है, इसलिए सारे नियम पढ़े नहीं जा सकते। फ़िंकल ने पढ़ी जा सकने वाली पंक्तियों और बोर्ड के आकार से सबसे सुसंगत खेल गढ़ा; दूसरे विद्वानों ने और रूप भी सुझाए हैं।"]},{"h":"आख़िरी खिलाड़ी भारत में","p":["बाद में फ़िंकल को पता चला कि दक्षिण भारत के कोच्चि (कोचीन) का यहूदी समुदाय हाल तक बहुत मिलते‑जुलते बोर्ड पर बीस ख़ानों वाला खेल खेलता था।","1950 के दशक में इस्राइल जाने तक यह खेल घरों में पीढ़ी‑दर‑पीढ़ी चलता रहा। शायद यह प्राचीन व्यापार‑मार्गों से भारत पहुँचा और चार हज़ार से ज़्यादा साल ज़िंदा रहा।"]}],"tl":[["लगभग 2600–2400 ई.पू.","उर के शाही मक़बरों में बीस ख़ानों वाले बोर्ड रखे गए"],["8वीं सदी ई.पू.","असीरियाई महल के फाटक‑रक्षक की मूर्ति के आधार पर बोर्ड खुरचा गया"],["177/176 ई.पू.","बेबीलोन के एक लिपिक ने नियमों की पटिया की नक़ल की"],["1922–1934","वूली ने उर की खुदाई की और बोर्ड पाए"],["1980 के दशक की शुरुआत","फ़िंकल ने पटिया पढ़ी और नियम दोबारा बनाए"],["1950 के दशक तक","दक्षिण भारत के कोच्चि में बहुत मिलता‑जुलता खेल खेला गया"]]},"liubo":{"title":"लिउबो क्यों लुप्त हो गया?","lead":"हान काल में सम्राट से लेकर आम लोग तक इसे खेलते थे। कुछ सदियों में इसके नियम तक भुला दिए गए।","s":["लिउबो हान काल (206 ईसा पूर्व – 220 ईसवी) के चीन का बड़ा शौक़ था। यह क़ब्रों की मूर्तियों, पत्थर की नक़्क़ाशी और यहाँ तक कि दर्पणों की सजावट में भी दिखता है, और अमर देवताओं को अक्सर इसे खेलते दिखाया गया है।","हान के पतन के बाद लिउबो तेज़ी से घटा, और लगता है कि तांग काल तक इसके नियम खो चुके थे। कारण साफ़ नहीं है; एक राय है कि खिलाड़ी वेइची (गो) जैसे दूसरे खेलों की ओर मुड़ गए।","बचे रहे बोर्ड और उपकरण। बोर्डों पर T, L और V आकृतियों का ख़ास नक़्शा खुदा है, और चालें शायद पतली छड़ियाँ फेंककर तय होती थीं। यही नक़्शा तथाकथित TLV दर्पणों पर भी है।","लिखित सुराग भी धीरे‑धीरे जुट रहे हैं। 1993 में जियांगसू के यिनवान की एक हान क़ब्र से बोर्ड‑चित्र का प्रयोग करने वाला भविष्य‑कथन का पाठ मिला। 2010 के दशक में खोदी गई हाइहुन के मार्क्विस लिउ हे की क़ब्र से लिउबो से जुड़ी एक हज़ार से ज़्यादा बाँस की पट्टियाँ मिलीं, जिन पर अध्ययन जारी है।","एटलस का लिउबो इन्हीं सुरागों पर आधारित एक पुनर्निर्माण है। विद्वान इसे थोड़े अलग‑अलग ढंग से गढ़ते हैं, और असली नियम अभी पूरी तरह ज्ञात नहीं — नई खोजें खेलने का तरीका बदल भी सकती हैं।"],"quiz":[["लिउबो किस राजवंश में बहुत लोकप्रिय था?","हान","मिंग","छिंग","सोंग"],["लिउबो से जुड़ी एक हज़ार से ज़्यादा बाँस की पट्टियाँ कहाँ मिलीं?","हाइहुन के मार्क्विस लिउ हे की क़ब्र में","प्रथम सम्राट के मक़बरे में","दुनहुआंग की गुफ़ाओं में","निषिद्ध नगर में"],["लिउबो में चाल तय करने के लिए शायद क्या फेंका जाता था?","पतली छड़ियाँ","बीस फलकों वाला पासा","लट्टू","चित्रों वाले पत्ते"]],"kf":["वारिंग स्टेट्स से हान काल (5वीं सदी ई.पू. – तीसरी सदी ई.) तक चीन में बेहद लोकप्रिय","T, L और V आकार की रेखाओं वाला बोर्ड; चाल के लिए पतली छड़ें फेंकी जाती थीं","हान के पतन के बाद तेज़ी से भुला दिया गया; नियम आज भी पूरी तरह मालूम नहीं"],"more":[{"h":"TLV बोर्ड","p":["लिउबो का बोर्ड वर्गाकार होता है — बीच में एक वर्ग, हर भुजा के बीच में T, उसके आसपास L और कोनों में V के आकार की रेखाएँ। माना जाता है कि मोहरे इन रेखाओं पर और इनके बीच चलते थे।","यही रेखाएँ दर्पणों की पीठ (\"TLV दर्पण\") और धूप‑घड़ियों पर भी मिलती हैं। कुछ विद्वान बोर्ड को आकाश, धरती और चारों दिशाओं वाले ब्रह्मांड का नक़्शा मानते हैं — यानी लिउबो सिर्फ़ मनोरंजन नहीं था।"],"cap":["लिउबो बोर्ड की रेखाएँ (TLV नमूना): बीच में वर्ग, हर भुजा पर T, कोनों की ओर L और V"]},{"h":"कैसे खेलते थे","p":["ज़्यादातर विद्वान मानते हैं कि हर खिलाड़ी के पास छह मोहरे थे और चाल तय करने के लिए बाँस की पतली छड़ें फेंकी जाती थीं। नाम का \"छह\" (लिउ) इन्हीं छह छड़ों या मोहरों से आया बताया जाता है।","आगे बढ़ा मोहरा शायद ताक़तवर \"उल्लू\" (श्याओ) बन जाता था। लगभग तीसरी सदी ई.पू. की \"चू के गीत\" की कविता \"आत्मा का आवाहन\" में पंक्ति है: \"उल्लू बनकर धावा बोलते हैं और पुकारते हैं ‘पाँच सफ़ेद!’\"। ग्रंथों में बोर्ड के बीच के \"पानी\" में \"मछली\" पकड़ने वाले खेल का भी ज़िक्र है।"],"cap":["हान मक़बरे के लिए बनी, लिउबो खेलती दो मूर्तियाँ (मेट्रोपॉलिटन म्यूज़ियम ऑफ़ आर्ट)"]},{"h":"मक़बरों से मिले सेट","p":["हूनान के चांगशा में मावांगदुई के मक़बरा 3 (लगभग 168 ई.पू.) में लाख के डिब्बे में बोर्ड, मोहरे और छड़ों का पूरा सेट मिला — ताकि मृतक परलोक में भी खेल सके।","मक़बरों की दीवारों की नक़्क़ाशियों में अमर प्राणी अक्सर पहाड़ की चोटियों पर लिउबो खेलते दिखते हैं। यह खेल अमरता और लंबी उम्र की दुनिया से जुड़ा था।"],"cap":["संग्रहालय का लिउबो बोर्ड — संग्रह कक्ष में इसे 3D में देखें"]}],"tl":[["5वीं–3वीं सदी ई.पू. (वारिंग स्टेट्स)","लिउबो बोर्ड मक़बरों में रखे जाने लगे"],["लगभग 3वीं सदी ई.पू.","\"आत्मा का आवाहन\" में लिउबो की बाज़ी का वर्णन"],["लगभग 168 ई.पू.","मावांगदुई मक़बरा 3 में पूरा सेट रखा गया"],["206 ई.पू. – 220 ई. (हान)","सम्राट से आम लोगों तक लोकप्रिय; नक़्क़ाशियों और दर्पणों पर"],["तांग (7वीं–10वीं सदी)","माना जाता है कि नियम भुला दिए गए थे"],["1993","यिनवान हान मक़बरों से बोर्ड वाला भविष्यवाणी का लेख मिला"],["2010 का दशक","हाइहुन के मार्क्विस लिउ हे के मक़बरे में लिउबो की बाँस‑पट्टियाँ मिलीं"]]},"zeno":{"title":"सम्राट ज़ेनो का बदक़िस्मत पासा","lead":"डेढ़ हज़ार साल पहले एक सम्राट ने पासे फेंके — और नतीजा एक कविता में आज तक बचा है।","s":["रोमन लोगों को ताबुला बहुत पसंद था: 24 खानों वाले बोर्ड पर पासों से खेली जाने वाली दौड़, जो बैकगैमन की पूर्वज है। बेईमानी रोकने के लिए वे पासा‑मीनार भी इस्तेमाल करते थे, जिसके भीतर पासे लुढ़ककर गिरते थे।","लगभग 480 ईसवी में पूर्वी रोमन सम्राट ज़ेनो ताबुला खेल रहे थे। उनके तीन पासों पर 2, 5 और 6 आए। नियमों के अनुसार चलने के अलावा कोई चारा नहीं था, और बोर्ड पर आठ गोटियाँ अकेली और असुरक्षित रह गईं।","यह बाज़ी अगाथियास ने दर्ज की, जो ज़ेनो के कुछ दशक बाद छठी सदी में रहे इतिहासकार और कवि थे। उनकी छोटी कविता (एपिग्राम) गोटियों की स्थिति तक बताती है — किसी प्राचीन बाज़ी का दुर्लभ अभिलेख।","19वीं सदी में फ़्रांसीसी विद्वान बेक द फ़ूकिएर ने कविता से स्थिति और नियम निकाले: हर खिलाड़ी की पंद्रह गोटियाँ और तीन पासे। सभी गोटियाँ बोर्ड के बाहर से शुरू होती हैं और दोनों खिलाड़ी एक ही दिशा में चलते हैं।","आज के बैकगैमन से अलग, ताबुला में तीन पासे थे, शुरुआत में बोर्ड पर कोई गोटी नहीं होती थी, और डबलिंग क्यूब नहीं था। एक सम्राट की बदक़िस्मती की बदौलत हम जानते हैं कि ताबुला कैसा था।"],"quiz":[["ज़ेनो के पासों पर क्या आया?","2, 5 और 6","6, 6 और 6","1, 1 और 1","3, 4 और 5"],["बाज़ी को कविता में किसने दर्ज किया?","अगाथियास","होमर","प्लिनी","सिसरो"],["ताबुला और आज के बैकगैमन में एक अंतर क्या है?","ताबुला में तीन पासे थे","हर खिलाड़ी की तीस गोटियाँ","12 खानों का बोर्ड","गोटियाँ उल्टी चलती हैं"]],"kf":["ताबुला 24 बिंदुओं और तीन पासों से खेला जाता था — बैकगैमन का पूर्वज","लगभग 480 ई. की सम्राट ज़ेनो की बाज़ी, स्थिति सहित, एक कविता में बची है","रोमनों ने बेईमानी रोकने के लिए \"पासा‑मीनार\" तक बनाई"],"more":[{"h":"ताबुला का बोर्ड","p":["ताबुला का बोर्ड आज के बैकगैमन की तरह 12‑12 की दो पंक्तियों में 24 बिंदुओं का होता है। हर खिलाड़ी की पंद्रह गोटियाँ शुरू में बोर्ड के बाहर होती थीं; तीन पासों के अनुसार उन्हें अंदर लाया जाता, चक्कर लगवाया जाता और बाहर निकाला जाता।","बैकगैमन से बड़ा अंतर यह है कि दोनों खिलाड़ी एक ही दिशा में चलते हैं। अकेली खड़ी गोटी पर विरोधी आ जाए तो वह मारी जाती और उसे फिर से अंदर लाना पड़ता। ज़ेनो की आठ गोटियाँ ठीक ऐसी ही असुरक्षित थीं।"],"cap":["ताबुला बोर्ड: 12‑12 की दो पंक्तियों में 24 बिंदु; दोनों खिलाड़ियों की गोटियाँ एक ही दिशा (तीर) में चलती हैं"]},{"h":"बेईमानी रोकने का यंत्र","p":["रोमन पासों के दीवाने थे। क़ानून जुए पर रोक लगाता था — कहते हैं केवल सर्दियों के सैटर्नेलिया उत्सव में छूट थी — पर दाँव कभी नहीं रुके, न हाथ की सफ़ाई वाली बेईमानी।","इसीलिए पासा‑मीनार बनी: ऊपर डाले गए पासे भीतर की पट्टियों से टकराकर नीचे लुढ़कते निकलते हैं। जर्मनी के एक विला से मिली चौथी सदी की मीनार पर जालीदार अक्षरों में लिखा है: \"पिक्ट हारे, दुश्मन नष्ट — निश्चिंत होकर खेलो\"।"],"cap":["फ़ेटवाइस‑फ़्रॉइत्सहाइम की पासा‑मीनार (चौथी सदी) — संग्रह कक्ष में इसे 3D में देखें"]},{"h":"सम्राट और पासे","p":["सिर्फ़ ज़ेनो ही नहीं। इतिहासकार सुएटोनियस बताते हैं कि पहली सदी के सम्राट क्लॉडियस को पासे इतने प्रिय थे कि उन्होंने इस कला पर एक किताब लिखी और अपनी गाड़ी ऐसी बनवाई कि खेलते समय बोर्ड न खिसके।","रोमन स्थलों से 36 अक्षरों वाले, छह‑छह अक्षरों के शब्दों में बने बहुत से बोर्ड भी मिलते हैं; हर अक्षर एक ख़ाने का काम करता था, और कुछ पर ऐसे ताने खुदे हैं: \"उठो, तुम्हें खेलना नहीं आता; खिलाड़ी को जगह दो\"।"],"cap":["ताबुला और पासे सम्राटों से सैनिकों तक सबके मनोरंजन थे (\"संयोग\" कक्ष में घनाकार पासे फेंकें)"]}],"tl":[["पहली सदी","सम्राट क्लॉडियस पासों के खेल पर किताब लिखते हैं"],["चौथी सदी","जर्मनी के एक विला में पासा‑मीनार इस्तेमाल होती है"],["लगभग 480","सम्राट ज़ेनो की बदक़िस्मत बाज़ी"],["छठी सदी","अगाथियास बाज़ी को कविता में ढालते हैं"],["लगभग 10वीं सदी","कविता \"यूनानी संकलन\" में शामिल होती है"],["1869","बेक द फ़ूकिएर स्थिति और नियम सुलझाते हैं"],["1934","आर. जी. ऑस्टिन ज़ेनो की बाज़ी की विस्तार से फिर जाँच करते हैं"]]},"sugoroku":{"title":"प्रतिबंधित सुगोरोकु","lead":"शासक रोकते रहे, लोग खेलते रहे। जापान में बोर्ड वाले सुगोरोकु की कहानी, प्राचीन काल से एदो काल तक।","s":["शोसोइन के ख़ज़ाने में एक सुगोरोकु बोर्ड है, जो परंपरा के अनुसार सम्राट शोमु को बहुत प्रिय था। यह काग़ज़ का चित्र‑वाला सुगोरोकु नहीं, बल्कि बान‑सुगोरोकु है, जिसमें बोर्ड पर सफ़ेद और काली गोटियाँ चलाई जाती हैं — बैकगैमन का रिश्तेदार।","सुगोरोकु जल्दी ही जुए से जुड़ गया। निहोन शोकि के अनुसार साम्राज्ञी जितो ने 689 में इस पर रोक लगाई।","757 से लागू योरो संहिता में भी भिक्षुओं और भिक्षुणियों के सुगोरोकु खेलने पर रोक थी। रोक बार‑बार लगाई गई — यानी उसका पालन नहीं होता था।","हेइआन काल में भी सुगोरोकु लोकप्रिय रहा और \"तकिये की किताब\" तथा \"गेंजी की कथा\" में आता है। \"हेइके की कथा\" बताती है कि संन्यस्त सम्राट शिराकावा ने तीन चीज़ें गिनाईं जो उनके वश में नहीं थीं: कामो नदी का पानी, सुगोरोकु के पासे और हिएई पर्वत के योद्धा‑भिक्षु।","एदो काल के काष्ठ‑छापों में अब भी लड़कियाँ घर में बान‑सुगोरोकु खेलती दिखती हैं। पर मेइजी युग तक बोर्ड वाला खेल लगभग ग़ायब हो गया, और \"सुगोरोकु\" का अर्थ काग़ज़ का चित्र‑खेल हो गया।"],"quiz":[["शोसोइन बोर्ड जैसा बान‑सुगोरोकु किस खेल का रिश्तेदार है?","बैकगैमन","शोगी","गो","ताश"],["निहोन शोकि के अनुसार 689 में सुगोरोकु पर किसने रोक लगाई?","साम्राज्ञी जितो","सम्राट शोमु","सम्राट कम्मु","सम्राट मेइजी"],["शिराकावा के वश में कामो नदी और योद्धा‑भिक्षु नहीं थे — और क्या?","सुगोरोकु के पासे","शोगी के मोहरे","गो के पत्थर","केमारी की गेंद"]],"kf":["बान‑सुगोरोकु बैकगैमन का रिश्तेदार है, जापान में 7वीं सदी में खेला जाता था","जुए के कारण बार‑बार रोका गया, पहली बार 689 में महारानी जितो ने","मेइजी काल तक लगभग भुला दिया गया, और \"सुगोरोकु\" काग़ज़ के चित्र‑खेल का नाम बन गया"],"more":[{"h":"शोसोइन का बोर्ड","p":["शोसोइन का बोर्ड शीशम (रोज़वुड) का है, जिस पर हाथीदाँत और रंगी लकड़ी की बारीक जड़ाई है। इसमें 24 ख़ाने हैं, दोनों ओर बारह‑बारह, और बीच की पट्टी पर फूल बने हैं।","शोसोइन में काँच और पत्थर की बहुत‑सी सुगोरोकु गोटियाँ भी रखी हैं। बान‑सुगोरोकु पंद्रह सफ़ेद, पंद्रह काली गोटियों और दो पासों से खेला जाता है — लगभग बैकगैमन जैसा सामान। माना जाता है कि यह फ़ारसी नर्द से चीन होते हुए आया।"],"cap":["शोसोइन का जड़ाऊ शीशम का सुगोरोकु बोर्ड — संग्रह कक्ष में इस पर खेलें"]},{"h":"कैसे खेलते हैं","p":["हर खिलाड़ी पंद्रह गोटियाँ तय क्रम में रखता है और दो पासों के अनुसार चलता है। सफ़ेद और काली उलटी दिशाओं में घूमती हैं; जो पहले अपनी सारी गोटियाँ आख़िरी छह ख़ानों में जमा कर ले, वह जीतता है।","अकेली गोटी पीटी जाकर शुरुआत पर लौटाई जा सकती है। दो या ज़्यादा गोटियों वाले ख़ाने में विरोधी नहीं आ सकता, इसलिए हुनर है नाकेबंदी बनाना। संग्रह कक्ष में शोसोइन के बोर्ड पर ऐसे ही खेल सकते हैं।"],"cap":["बान‑सुगोरोकु बोर्ड (रेखाचित्र): 24 ख़ाने, सफ़ेद और काली उलटी दिशाओं में"]},{"h":"रोक और चलन","p":["जितो के बाद भी सुगोरोकु पर कई बार रोक लगी, क्योंकि जुए में सब कुछ हार जाने वाले कभी कम नहीं हुए। कामाकुरा शोगुनत ने भी सुगोरोकु पर दाँव के ख़िलाफ़ क़ानून बनाए।","दूसरी ओर, यह अभिजात वर्ग का एक हुनर भी था। सुंदर बोर्ड दुल्हन के दहेज़ में जाता था, और एदो काल में लाख‑चित्रित शानदार बोर्ड बने। जुए के औज़ार के रूप में नापसंद, ख़ज़ाने के रूप में प्रिय — बान‑सुगोरोकु के दोनों चेहरे थे।"],"cap":["एदो काल के एक चित्र में बान‑सुगोरोकु (चित्रों में खेल कक्ष)"]}],"tl":[["7वीं सदी","बान‑सुगोरोकु चीन से आया"],["689","महारानी जितो ने सुगोरोकु पर रोक लगाई (निहोन शोकी)"],["8वीं सदी","जड़ाऊ बोर्ड शोसोइन में पहुँचा"],["757","योरो संहिता ने भिक्षु‑भिक्षुणियों के लिए इसे वर्जित किया"],["हेइआन काल","\"तकिये की किताब\" और \"गेंजी की कथा\" में सुगोरोकु"],["12वीं सदी","शिराकावा की \"सुगोरोकु के पासों\" वाली शिकायत (हेइके की कथा)"],["एदो काल","दहेज़ के लिए शानदार बोर्ड बने"],["मेइजी काल","बान‑सुगोरोकु लगभग खेलना बंद हुआ"]]},"queen":{"title":"शतरंज का वज़ीर सबसे ताक़तवर मोहरा कैसे बना","lead":"आज का सबसे ताक़तवर मोहरा कभी एक सलाहकार था, जो केवल एक खाना तिरछा चल सकता था।","s":["शतरंज भारत से फ़ारस और फिर अरब जगत पहुँचा। फ़ारसी महाकाव्य शाहनामा में विद्वान बुज़ुर्गमेहर भारत से भेजी गई शतरंज की पहेली सुलझाते हैं। उन बोर्डों पर राजा के पास \"फ़र्ज़\" यानी सलाहकार (वज़ीर) खड़ा होता था।","फ़र्ज़ केवल एक खाना तिरछा चलता था — बहुत कमज़ोर मोहरा। ईरान के निशापुर के 12वीं सदी के शतरंज सेट में यह राजा से छोटे सिंहासन जैसा है।","यूरोप पहुँचकर सलाहकार रानी बन गया; 12वीं सदी के लुईस मोहरों में भी रानियाँ हैं। पर नाम बदलने से चाल नहीं बदली: वह कमज़ोर ही रही।","बड़ा बदलाव 15वीं सदी के अंत में स्पेन में आया। लगभग 1475 में वालेंसिया में लिखी कविता Scachs d’amor (\"प्रेम की शतरंज\") को आधुनिक वज़ीर — जो पंक्ति, स्तंभ और तिरछे में कितनी भी दूर चले — का सबसे पुराना अभिलेख माना जाता है। फिर लुसेना (1497) और दामियानो (1512) की पुस्तकों ने नया नियम पूरे यूरोप में फैलाया।","वज़ीर इतना ताक़तवर क्यों हुआ, यह निश्चित नहीं। कुछ कहते हैं कि लोग तेज़ बाज़ियाँ चाहते थे; कुछ इसाबेला प्रथम जैसी शक्तिशाली रानियों के प्रभाव की बात करते हैं। जो भी हो, इस बदलाव ने शतरंज को आज के खेल के बहुत क़रीब ला दिया।"],"quiz":[["फ़ारसी और अरबी शतरंज में आज के वज़ीर की जगह कौन‑सा मोहरा था?","फ़र्ज़ (सलाहकार)","हाथी","रथ","घोड़ा"],["मूल फ़र्ज़ कैसे चलता था?","एक खाना तिरछा","सीधी रेखा में कितना भी","दो खाने कूदकर","चल नहीं सकता था"],["आधुनिक वज़ीर के सबसे पुराने अभिलेख वाली कविता कहाँ लिखी गई?","वालेंसिया, 15वीं सदी","भारत, छठी सदी","लुईस, 12वीं सदी","लंदन, 19वीं सदी"]],"kf":["रानी (वज़ीर) का पूर्वज फ़ारसी‑अरबी \"फ़र्ज़\" (सलाहकार) था, जो तिरछा बस एक ख़ाना चलता था","आज की ताक़तवर रानी पहली बार लगभग 1475 में स्पेन में लिखित मिलती है","छपी किताबों ने कुछ ही दशकों में नए नियम पूरे यूरोप में फैला दिए"],"more":[{"h":"कमज़ोर सलाहकार","p":["फ़र्ज़ बस तिरछा एक ख़ाना चल सकता था — आज की रानी से बिल्कुल अलग, जो बिसात के एक छोर से दूसरे तक दौड़ जाती है। तब शतरंज धीमी थी, और एक बाज़ी घंटों चल सकती थी।","हाथी (आज का ऊँट/बिशप) भी बस तिरछा दूसरे ख़ाने पर कूदता था। प्यादा आख़िरी पंक्ति तक पहुँचकर पदोन्नत होता था — पर सिर्फ़ इसी कमज़ोर फ़र्ज़ में।"],"cap":["फ़र्ज़ (बाएँ) और आज की रानी (दाएँ) कहाँ तक चल सकते हैं"]},{"h":"\"रानी की शतरंज\" और \"पागल शतरंज\"","p":["नई रानी के आने पर स्पेन में इस खेल को \"रानी की शतरंज\" कहा गया, और इटली में उसकी तेज़ी के कारण \"पागल शतरंज\" (scacchi alla rabbiosa)। लगभग उसी समय बिशप भी तिरछा कितनी भी दूर सरकने लगा।","मोहरे ताक़तवर हुए तो खेल तेज़ और तीखा हो गया। कुछ ही चालों में जिताने वाले जालों और तय शुरुआती चालों पर किताबें आने लगीं — शतरंज अध्ययन का खेल बन गई।"],"cap":["लिबेराले दा वेरोना, \"शतरंज खेलते लोग\" (लगभग 1475) — ठीक उसी समय का चित्र जब नई रानी जन्मी"]},{"h":"रानी ही क्यों?","p":["सलाहकार रानी क्यों बना, यह पक्का नहीं। राजा के पास खड़े मोहरे को उसकी पत्नी मानना शायद स्वाभाविक लगा। लैटिन में \"फ़र्ज़\" \"फ़र्सिया\" बना और फिर मोहरे को \"रेजिना\" यानी रानी कहा जाने लगा।","उसके ताक़तवर होने की वजह पर भी बहस है: खेल तेज़ करने के लिए, या इसलिए कि वह कास्तील की इसाबेला प्रथम जैसी शक्तिशाली रानियों का दौर था। इतिहासकार मर्लिन यालोम ने इस बदलाव को मध्ययुग में स्त्रियों की स्थिति से जोड़ा।"],"cap":["लुईस द्वीप के शतरंज‑मोहरों की रानी (12वीं सदी) — अभी पुरानी, कमज़ोर चाल के साथ"]}],"tl":[["लगभग 6वीं सदी","भारत में शतरंज का पूर्वज चतुरंग जन्मा"],["7वीं–9वीं सदी","फ़ारस और अरब जगत में खेला गया, राजा के पास फ़र्ज़"],["लगभग 10वीं सदी","शतरंज यूरोप पहुँची"],["12वीं सदी","लुईस द्वीप के मोहरों में रानियाँ (अभी कमज़ोर)"],["लगभग 1475","वालेंसिया की कविता \"स्काक्स दामोर\" में नई चाल"],["1497","लुसेना की शतरंज‑पुस्तक स्पेन में छपी"],["1512","दामियानो की पुस्तक इटली में छपी, नए नियम फैले"]]},"senet":{"title":"सेनेट परलोक की यात्रा कैसे बना","lead":"मिस्र में लगभग तीन हज़ार साल खेला गया एक खेल आख़िरकार मृत्यु के बाद आत्मा की यात्रा का प्रतीक बन गया।","s":["सेनेट प्राचीन मिस्र का खेल है, जिसमें गोटियाँ दस‑दस खानों की तीन पंक्तियों वाले बोर्ड पर चलती हैं। लगभग 3100 ईसा पूर्व के पहले राजवंश की क़ब्रों में ऐसे टुकड़े मिले हैं जो सेनेट के बोर्ड हो सकते हैं। राजा शानदार बक्सों पर खेलते थे, आम लोग पत्थर पर खुरचे बोर्डों पर।","इसके नाम का अर्थ है \"गुज़रना\"। नए साम्राज्य (लगभग 1550 ईसा पूर्व से) में सेनेट को मृतक की आत्मा के परलोक से गुज़रने की यात्रा से जोड़ा जाने लगा।","\"मृतकों की पुस्तक\" के अध्याय 17 में मृतक एक अदृश्य प्रतिद्वंद्वी के साथ सेनेट खेलता दिखता है। रामेसेस द्वितीय की रानी नेफ़रतारी की क़ब्र की दीवार पर भी रानी सेनेट के बोर्ड के सामने बैठी है।","तूतनख़ामुन की क़ब्र में कम से कम पाँच खेल‑बक्से मिले। उनमें से एक, आबनूस और हाथीदाँत का बड़ा बक्सा, ऊपर सेनेट और दूसरी ओर बीस खानों वाला एक अलग खेल लिए है।","फिर भी नियमों को पूरी तरह समझाने वाला कोई पाठ नहीं मिला। 20वीं सदी में जेकिए, बेल और केंडल (1978) सहित कई विद्वानों ने बोर्डों, चित्रों और पाठ के टुकड़ों से अपने‑अपने ढंग से खेलने का तरीक़ा गढ़ा। एटलस का सेनेट भी शोध पर आधारित ऐसा ही एक तरीक़ा है।"],"quiz":[["\"सेनेट\" नाम का अर्थ क्या है?","गुज़रना","राजा का खेल","तीस घर","नदी पार करना"],["नए साम्राज्य में सेनेट को किससे जोड़ा गया?","आत्मा की परलोक‑यात्रा से","वर्षा के अनुष्ठानों से","युद्ध की योजनाओं से","फ़सल के शकुन से"],["तूतनख़ामुन की क़ब्र में कम से कम कितने खेल‑बक्से थे?","पाँच","एक","दो","सौ"]],"kf":["दुनिया के सबसे पुराने बोर्ड‑खेलों में से एक: 3 × 10 ख़ानों के बोर्ड पर गोटियाँ दौड़ती हैं","नाम का अर्थ है \"गुज़रना\"; नए साम्राज्य में यह परलोक से आत्मा की यात्रा बन गया","नियम बचे नहीं; आज के खेलने के तरीक़े 20वीं सदी के पुनर्निर्माण हैं"],"more":[{"h":"तीस ख़ाने और ख़ास ख़ाने","p":["सेनेट के बोर्ड में दस‑दस ख़ानों की तीन पंक्तियाँ, यानी तीस ख़ाने होते हैं। माना जाता है कि गोटियाँ पहली पंक्ति में बाएँ से दाएँ, दूसरी में दाएँ से बाएँ और तीसरी में फिर बाएँ से दाएँ — S बनाते हुए चलती थीं।","आख़िरी पाँच ख़ानों पर अक्सर ख़ास निशान होते थे। 26वाँ \"सुंदर घर\", 27वाँ \"पानी\" है; ज़्यादातर पुनर्निर्माणों में पानी में गिरी गोटी पीछे लौटती है। 28–30 पर अंक या परलोक के देवता बने होते थे।"],"cap":["सेनेट का बोर्ड। गोटियाँ S‑आकार में चलती हैं; आख़िरी पाँच ख़ानों (26–30) पर ख़ास निशान"]},{"h":"फेंकने वाली छड़ियों से चाल","p":["पासों की जगह चार छड़ियाँ फेंकी जाती थीं — एक ओर सपाट, दूसरी ओर गोल — या जानवरों की टखने की हड्डियाँ। कई विद्वान मानते हैं कि ऊपर आई सपाट तरफ़ों जितनी चाल होती थी, और कोई न हो तो पाँच।","यही गिनती दूर कोरिया की युत छड़ियों की भी है। संग्रहालय के \"संयोग\" कक्ष में छड़ियाँ फेंककर देखें कि कुछ अंक कितने ज़्यादा आते हैं।"],"cap":["मिस्र की फेंकने वाली छड़ियाँ (\"संयोग\" कक्ष में फेंकें)"]},{"h":"तूतनख़ामुन के खेल‑बक्से","p":["1922 में हॉवर्ड कार्टर द्वारा खोले गए तूतनख़ामुन के मक़बरे में कम से कम पाँच खेल‑बक्से थे। सबसे बड़ा आबनूस और हाथीदाँत का है, जिसमें गोटियों और छड़ियों के लिए दराज़ है।","उस दौर में दोनों ओर बोर्ड वाले बक्से आम थे: एक ओर सेनेट, दूसरी ओर उर के शाही खेल जैसा बीस ख़ानों का खेल। चाहा गया कि राजा परलोक में भी दोनों खेल सके।"],"cap":["तूतनख़ामुन का सेनेट बक्सा — संग्रह कक्ष में 3D में देखें और खेलें"]}],"tl":[["लगभग 3100 ई.पू.","पहले राजवंश के मक़बरे में सेनेट‑जैसे बोर्ड के टुकड़े"],["लगभग 2600 ई.पू.","पुराने साम्राज्य के मक़बरा‑चित्रों में खिलाड़ी"],["लगभग 1550 ई.पू. से","नया साम्राज्य: सेनेट परलोक‑यात्रा से जुड़ा"],["लगभग 1323 ई.पू.","तूतनख़ामुन के मक़बरे में पाँच खेल‑बक्से"],["लगभग 1250 ई.पू.","नेफ़र्तारी सेनेट के बोर्ड के सामने चित्रित"],["1922","कार्टर ने तूतनख़ामुन का मक़बरा खोला"],["1978","केंडल ने नियमों का पुनर्निर्माण छापा"]]},"lewis":{"title":"रेत से निकले शतरंज के मोहरे","lead":"1831 में एक स्कॉटिश द्वीप पर मिले मध्यकालीन मोहरे — और उसी कारख़ाने का एक और मोहरा, जो 188 साल बाद एक दराज़ से निकला।","s":["1831 में स्कॉटलैंड के उत्तर‑पश्चिम में लुईस द्वीप पर ज़्यादातर वालरस के दाँत से तराशे मोहरों का एक ख़ज़ाना मिला: 78 शतरंज के मोहरे, बोर्ड‑खेलों की 14 गोटियाँ और एक बकसुआ — कुल 93 वस्तुएँ।","वे ठीक कहाँ और कैसे मिले, यह साफ़ नहीं है। अक्सर पश्चिमी तट की उइग खाड़ी का नाम लिया जाता है, पर दूसरी जगहें भी सुझाई गई हैं। उन्हें वहाँ किसने और क्यों दबाया, यह भी अज्ञात है।","माना जाता है कि ये 12वीं सदी के अंत में नॉर्वे के ट्रॉन्डहाइम के आसपास बने: राजा, विचारमग्न रानियाँ, बिशप, ठिगने घोड़ों पर सवार घुड़सवार, और ढाल का किनारा चबाते पहरेदार — शायद नॉर्स गाथाओं के बेर्सेर्कर योद्धा।","आज 82 मोहरे ब्रिटिश म्यूज़ियम में और 11 स्कॉटलैंड के राष्ट्रीय संग्रहालय में हैं। लंबे समय से कहा जाता है कि पूरे सेट बनाने के लिए कुछ मोहरे कम हैं।","2019 में एक पहरेदार मोहरा, जिसे एडिनबरा के एक प्राचीन‑वस्तु विक्रेता ने 1964 में सिर्फ़ 5 पाउंड में ख़रीदा था और परिवार ने दराज़ में रखा था, लुईस मोहरों के कारख़ाने का माना गया। वह सॉदबी की नीलामी में 7,35,000 पाउंड में बिका।"],"quiz":[["लुईस पर मोहरे किस साल मिले?","1831","1066","1931","1700"],["मोहरे मुख्यतः किससे बने हैं?","वालरस के दाँत से","संगमरमर से","सोने से","काँच से"],["2019 में बिका पहरेदार मोहरा किस साल 5 पाउंड में ख़रीदा गया था?","1964","1831","1990","2018"]],"kf":["1831 में स्कॉटलैंड के लुईस द्वीप पर मिले 93 मोहरे और चकतियाँ","12वीं सदी के आख़िर में नॉर्वे में, ज़्यादातर वालरस के दाँत से तराशे गए","आज ब्रिटिश संग्रहालय और स्कॉटलैंड के राष्ट्रीय संग्रहालयों में बँटे हैं"],"more":[{"h":"78 शतरंज‑मोहरे","p":["78 मोहरों में 8 राजा, 8 रानियाँ, 16 बिशप, 15 घुड़सवार, 12 पहरेदार और 19 प्यादे हैं — कम से कम चार सेटों के हिस्से।","बिशप मुकुटनुमा टोपी (माइटर) पहने हैं। शतरंज का \"हाथी\" बिशप में यूरोप में बदला, और लुईस के मोहरे इसके सबसे शुरुआती उदाहरणों में हैं। कुछ पहरेदार अपनी ढाल चबाते हैं — माना जाता है कि ये उन्माद में लड़ने वाले \"बर्सर्कर\" योद्धा हैं।"],"cap":["लुईस द्वीप के शतरंज‑मोहरे (संग्रह कक्ष में 3D में देखें)","78 मोहरे क़िस्म के हिसाब से"]},{"h":"वालरस का दाँत और उत्तरी समुद्र","p":["ज़्यादातर मोहरे वालरस के दाँत के, कुछ व्हेल के दाँत के हैं। वालरस‑दाँत उत्तरी समुद्रों का ख़ज़ाना था, जो ग्रीनलैंड और उत्तरी नॉर्वे से लाया जाता था।","तब लुईस नॉर्वे के राजा के द्वीपों में था; 1266 की पर्थ संधि से यह स्कॉटलैंड को मिला। त्रोंहाइम के गिरजाघर के पास उसी तरह तराशे टुकड़े मिले हैं — यह सुराग़ कि मोहरे कहाँ बने।"],"cap":[]},{"h":"खोज की किंवदंती और आज की लोकप्रियता","p":["खोज के कई क़िस्से हैं: रेत से उन्हें खोद निकालने वाली गाय, या स्थानीय निवासी मैल्कम मैकलाउड। खोजने वाले ने जल्दी ही उन्हें बेच दिया और एडिनबरा होते हुए ज़्यादातर ब्रिटिश संग्रहालय ने ख़रीदे।","रूठे और मज़ेदार चेहरों वाले ये मोहरे आज बेहद लोकप्रिय हैं और इनकी नक़लें दुनिया भर में बिकती हैं। फ़िल्म \"हैरी पॉटर एंड द फ़िलॉसफ़र्स स्टोन\" (2001) की जादुई शतरंज में लुईस के मोहरों पर आधारित मोहरे थे।"],"cap":[]}],"tl":[["12वीं सदी का अंत","मोहरे नॉर्वे (त्रोंहाइम के आसपास) में बने"],["1266","पर्थ संधि से लुईस समेत द्वीप स्कॉटलैंड को मिले"],["1831","लुईस पर 93 वस्तुएँ एक साथ मिलीं"],["1831–32","ब्रिटिश संग्रहालय ने 82 ख़रीदीं"],["1888","स्कॉटलैंड के राष्ट्रीय संग्रहालय को 11 मिलीं"],["2001","\"हैरी पॉटर\" की जादुई शतरंज में दिखे"],["2019","5 पाउंड में ख़रीदा गया पहरेदार 7,35,000 पाउंड में बिका"]]},"tafl":{"title":"राजा का पलायन और एक ग़लत अनुवाद","lead":"वाइकिंग बोर्ड‑खेल के नियम 18वीं सदी की लैपलैंड यात्रा‑डायरी से निकाले गए।","s":["वाइकिंग युग के उत्तरी यूरोप में तफ़्ल नाम के बोर्ड‑खेल खेले जाते थे। बीच में राजा और उसके थोड़े से रक्षक, उन्हें घेरने वाली बड़ी सेना से लड़ते हैं — दो असमान पक्षों का खेल।","1932 में आयरलैंड के बैलिंडेरी में मिले 10वीं सदी के लकड़ी के बोर्ड में 7×7 छेद हैं; बीच का और चारों कोनों के छेद चिह्नित हैं — शायद राजा की जगह और उसके शरण‑स्थल।","पर नियमों का कोई मध्यकालीन विवरण लगभग नहीं बचा। एक अहम सुराग 25 वर्षीय प्रकृतिविद् लिनियस की 1732 की लैपलैंड (उत्तरी स्वीडन) यात्रा की डायरी है। वहाँ उन्होंने लिखा कि सामी लोग तबलुत नाम का खेल कैसे खेलते थे।","यह डायरी 1811 में अंग्रेज़ी अनुवाद में छपी, पर अनुवाद में ग़लतियाँ थीं। उस पर आधारित मरे का पुनर्निर्माण (1913) बरसों तक तफ़्ल का मानक नियम बना रहा।","बाद में खिलाड़ियों और शोधकर्ताओं ने ग़लती सुधारी, और आज नियमों के कई संस्करण खेले जाते हैं। एटलस का तफ़्ल उनमें से एक है।"],"quiz":[["लिनियस ने लैपलैंड में कौन‑सा खेल लिखा?","तबलुत","सेनेट","मनकाला","शतरंज"],["रक्षक किस मोहरे को कोने तक ले जाना चाहते हैं?","राजा","रानी","झंडा","जहाज़"],["ग़लतियों वाला अंग्रेज़ी अनुवाद कब छपा?","1811","1732","1932","1066"]],"kf":["बीच में एक राजा और कुछ रक्षक, जिन्हें बड़ी सेना घेरे रहती है — दो असमान पक्षों का खेल","वाइकिंग युग के उत्तरी यूरोप में खेला जाता था; बिसात 7×7 से 19×19 तक अलग-अलग आकार की","नियमों का सुराग लिनियस की 1732 की यात्रा-डायरी और उसका ग़लतियों वाला अंग्रेज़ी अनुवाद है"],"more":[{"h":"बैलिंडेरी की बिसात","p":["आयरलैंड के मध्य भाग में झील पर बनी बस्ती (क्रैनॉग) से मिली बैलिंडेरी की बिसात यू की लकड़ी की है। 7×7 के 49 छेदों में शायद ऐसी गोटियाँ लगाई जाती थीं जिनके नीचे खूँटी होती थी।","किनारे से इंसानी सिर के आकार का एक हत्था निकला है — यानी इसे साथ ले जाया जा सकता था। आयरिश स्रोतों में 7×7 के एक तफ़्ल ‘ब्रानडुव’ (काला कौआ) का नाम मिलता है; हो सकता है वह इसी बिसात पर खेला जाता हो।"],"cap":["बैलिंडेरी की बिसात (7×7) पर आयरलैंड के ‘ब्रानडुव’ की शुरुआती चाल। सुनहरे छल्ले बीच और चारों कोनों के निशान हैं"]},{"h":"लिनियस का तबलुत","p":["लिनियस ने जो तबलुत दर्ज किया, वह 9×9 की बिसात पर खेला जाता है। राजा बीच के सिंहासन पर खड़ा होता है; उसके 8 ‘स्वीडिश’ 16 ‘मस्कोवी’ से लड़ते हैं।","सभी गोटियाँ हाथी (रूक) की तरह सीधी रेखा में कितने भी खाने चलती हैं, और दो दुश्मनों के बीच फँसने पर मारी जाती हैं। राजा किनारे तक पहुँच जाए तो रक्षक जीतते हैं; उसे चारों ओर से घेर लें तो हमलावर। लिनियस ने लैटिन और स्वीडिश मिलाकर लिखा था, और अंग्रेज़ी अनुवाद में कई बातें बदल गईं।"],"cap":["लिनियस का दर्ज किया तबलुत (9×9): बीच के सिंहासन पर राजा, 8 रक्षक, 16 हमलावर। राजा किनारे के हरे खाने पर पहुँचे तो रक्षक जीतते हैं"]},{"h":"बड़ी होती बिसातें, मिटता खेल","p":["7×7 के अलावा 9×9, वेल्स की 11×11 और 19×19 तक की बिसातें थीं। सबसे बड़ी, ‘अलेआ एवांजेली’, 12वीं सदी की एक पांडुलिपि में बनी है, जिसमें लिखा है कि यह 10वीं सदी में इंग्लैंड के राजा एथेलस्टन के दरबार से आई।","12वीं–13वीं सदी में जब शतरंज उत्तरी यूरोप में फैला, तफ़्ल धीरे-धीरे भुला दिया गया। सिर्फ़ दूर लैपलैंड में तबलुत बचा रहा — और लिनियस ने संयोग से उसे लिख लिया। आज 11×11 की बिसात पर अंतरराष्ट्रीय टूर्नामेंट होते हैं और खेल को नए खिलाड़ी मिल रहे हैं।"],"cap":["लुईस द्वीप की खोज (12वीं सदी): शतरंज के मोहरों के साथ बिसात के खेल की 14 टिकियाँ मिलीं"]}],"tl":[["10वीं सदी","आयरलैंड में बैलिंडेरी की बिसात बनी"],["924–939","कहा जाता है कि एथेलस्टन के दरबार में अलेआ एवांजेली खेला गया"],["12वीं सदी","अलेआ एवांजेली एक पांडुलिपि में बनाया गया"],["12वीं–13वीं सदी","शतरंज उत्तरी यूरोप में फैला, तफ़्ल मिटता गया"],["1732","लिनियस ने लैपलैंड में तबलुत दर्ज किया"],["1811","डायरी का अंग्रेज़ी अनुवाद ‘लैकेसिस लैपोनिका’ छपा"],["1913","मरे ने ‘ए हिस्ट्री ऑफ़ चेस’ में तफ़्ल का पुनर्निर्माण किया"],["1932","बैलिंडेरी की बिसात मिली"]]},"goose":{"title":"बत्तख़ का खेल, एक राजा का उपहार","lead":"63 खानों की सर्पिल पर पासों की दौड़ एक राजा को भेंट की गई — और फिर पूरे यूरोप में खेली गई।","s":["बत्तख़ का खेल एक दौड़ है: पासा फेंकिए और 63 खानों की सर्पिल पर बीच के लक्ष्य तक बढ़िए। बत्तख़ वाले खाने पर रुकने पर उतने ही खाने फिर आगे बढ़ते हैं। कुआँ, क़ैदख़ाना और मृत्यु आपको रोकते हैं या शुरुआत पर लौटा देते हैं।","माना जाता है कि यह 16वीं सदी के इटली में जन्मा। कहा जाता है कि टस्कनी के ग्रैंड ड्यूक फ़्रांचेस्को प्रथम दे मेदिची ने 1574 से 1587 के बीच यह खेल स्पेन के राजा फ़िलिप द्वितीय को भेंट किया।","इंग्लैंड में लंदन के मुद्रक जॉन वुल्फ़ ने 1597 में \"बत्तख़ का नया और बहुत मज़ेदार खेल\" दर्ज कराया। 17वीं‑18वीं सदी में यह पूरे यूरोप में बेहद लोकप्रिय रहा।","काग़ज़ पर छपकर यह नए‑नए चित्रों वाले अनगिनत रूपों में फैला: भूगोल सिखाने वाले बोर्ड, कहानियों और नीतिकथाओं के बोर्ड, यहाँ तक कि विज्ञापन के बोर्ड भी। माना जाता है कि बाद के कई दौड़‑खेलों का यह आदर्श बना।","मेट्रोपॉलिटन म्यूज़ियम ऑफ़ आर्ट के एक दोतरफ़ा बोर्ड पर एक ओर बत्तख़ का खेल और दूसरी ओर शतरंज है। माना जाता है कि इसे 16वीं सदी के अंत में भारत के गुजरात के कारीगरों ने बनाया; यह बत्तख़ के खेल का सबसे पुराना बचा बोर्ड हो सकता है।"],"quiz":[["बत्तख़ के खेल में कितने खाने होते हैं?","63","64","100","30"],["कहा जाता है कि यह खेल स्पेन के राजा को किसने भेंट किया?","फ़्रांचेस्को प्रथम दे मेदिची","नेपोलियन","एलिज़ाबेथ प्रथम","लुई चौदहवें"],["बत्तख़ वाले खाने पर रुकने पर क्या होता है?","उतने ही खाने फिर आगे बढ़ते हैं","शुरुआत पर लौटते हैं","एक बारी छूटती है","प्रतिद्वंद्वी से जगह बदलते हैं"]],"kf":["पासा फेंककर 63 खानों की कुंडली पर बीच की मंज़िल तक पहुँचने की दौड़","16वीं सदी के इटली में जन्मा; कहा जाता है कि मेदिची परिवार ने इसे स्पेन के राजा को भेंट किया","छपे पन्नों के रूप में फैला; नए चित्रों और विषयों वाले अनगिनत संस्करण बने"],"more":[{"h":"63 खानों की कुंडली","p":["सबसे प्रसिद्ध संस्करण में हंसों के अलावा कुछ ख़ास खाने हैं। 6 पर पुल आपको 12 तक ले जाता है; 19 की सराय में एक बारी छूटती है; 31 के कुएँ और 52 की जेल में तब तक फँसे रहते हैं जब तक कोई दूसरा खिलाड़ी आकर छुड़ा न दे।","42 की भूलभुलैया 30 पर लौटा देती है, और 58 की मृत्यु शुरुआत पर। 63 पर ठीक-ठीक अंक से पहुँचना होता है; जितने अंक ज़्यादा हों, उतना पीछे लौटना पड़ता है। आख़िरी क़दम सबसे कठिन है।"],"cap":["63 खाने बाहर से भीतर की कुंडली में। हरा: हंस; नीला: पुल; पीला: रुकावटें (सराय, कुआँ, जेल); लाल: पीछे भेजने वाले (भूलभुलैया, मृत्यु); सुनहरा: मंज़िल"]},{"h":"नौ की पहेली","p":["हंस 5, 9, 14, 18… पर हैं, 4 और 5 के बदलते अंतर से। 9 के हर गुणज पर हंस है, इसलिए 9 पर पहुँचा 9 का अंक आपको 18, 27… और सीधे 63 तक ले जाता।","इसीलिए दो पासों वाले संस्करणों में एक ख़ास नियम है: पहली चाल में 6 और 3 आए तो 26 पर, 5 और 4 आए तो 53 पर जाते हैं। 63 यानी 7×9; इसे 63 वर्ष की उम्र से जोड़ा गया है, जिसे तब जीवन का सबसे ख़तरनाक साल माना जाता था।"],"cap":["हंस बारी-बारी से 4 और 5 खानों के अंतर पर हैं, इसलिए 9 के हर गुणज पर हंस है। पहली चाल में 9 आए तो हंस से हंस पर कूदते हुए सीधे 63"]},{"h":"छपाई से फैलाव","p":["बिसातें ताँबे की प्लेटों और लकड़ी के ठप्पों से छपीं और सस्ती हो गईं। फ़्रांस में इसे जू द ल्वा, स्पेन में ख़ुएगो दे ला ओका कहा गया; स्पेन में “हंस से हंस तक” वाली तुकबंदी आज भी कहावत है।","नए चित्रों वाले संस्करण लगातार आते रहे: भूगोल और इतिहास सिखाने वाली बिसातें, फ़्रांसीसी क्रांति या नेपोलियन पर बनी बिसातें, यहाँ तक कि सामान के विज्ञापन भी। उसी 63 खानों के रास्ते पर हर युग ने अपनी चिंताएँ उकेरीं।"],"cap":[]}],"tl":[["16वीं सदी","इटली में जन्म माना जाता है"],["1574–87","कहा जाता है कि फ़्रांचेस्को प्रथम दे मेदिची ने इसे स्पेन के फ़िलिप द्वितीय को भेंट किया"],["16वीं सदी का अंत","गुजरात (भारत) में दोतरफ़ा बिसात बनी: एक ओर हंस का खेल, दूसरी ओर शतरंज"],["1597","जॉन वुल्फ़ ने लंदन में इसे छपाई के लिए दर्ज कराया"],["17वीं–18वीं सदी","पूरे यूरोप में लोकप्रिय, विषय-आधारित संस्करण बढ़े"],["1790 का दशक","फ़्रांसीसी क्रांति पर बिसातें बनीं"],["19वीं सदी","कई देशों में बच्चों के खेल के रूप में बड़े पैमाने पर छपा"]]},"shogi":{"title":"शोगी में पकड़े मोहरे वापस रखने का नियम कब बना?","lead":"शतरंज के पूरे परिवार में सिर्फ़ शोगी में पकड़े गए मोहरे को अपना बनाकर फिर बोर्ड पर रखा जा सकता है। यह नियम कब और क्यों बना?","s":["शतरंज का भारतीय पूर्वज पूरब और पश्चिम में फैला; जापान में वह शोगी बना। जापान के सबसे पुराने शोगी मोहरे 16 हैं, जो 1990 के दशक की शुरुआत में नारा के कोफ़ुकु‑जी के पुराने परिसर में खुदाई से मिले। उनके साथ 1058 (तेनकी 6) की तारीख़ वाली एक पट्टी मिली, इसलिए मोहरे भी उसी समय के माने जाते हैं।","उस दौर के लेखों में भी शोगी आता है। 11वीं सदी के मध्य की \"शिन सारुगाकु‑की\" में इसका नाम है, और हेइआन काल के अंत के अभिलेख जुटाने वाली \"निचूरेकी\" में राजा, सोने‑चाँदी के सेनापति, घोड़े, भाले और प्यादों वाले \"हेइआन शोगी\" का वर्णन है।","कामाकुरा और मुरोमाची काल में ज़्यादा मोहरों वाले कई बड़े रूप बने। आज के खेल के पूर्वज \"छोटे शोगी\" में रुख़ और ऊँट जोड़े गए — और एक ऐसा मोहरा भी, जो अब नहीं है: नशे में धुत हाथी।","माना जाता है कि पकड़े मोहरे वापस रखने का नियम लगभग 16वीं सदी में बना। परंपरा कहती है कि सम्राट गो‑नारा ने छोटे शोगी से नशे वाला हाथी हटवाया, और माना जाता है कि यह नियम भी लगभग तभी शुरू हुआ।","ऐसा क्यों हुआ, साफ़ नहीं। एक व्याख्या यह है: दोनों पक्षों के मोहरे एक ही रंग के होते हैं और सिर्फ़ दिशा से पहचाने जाते हैं, इसलिए पकड़ा मोहरा आसानी से दोबारा इस्तेमाल हो जाता है। इसी नियम से बोर्ड ख़ाली नहीं होता और ड्रॉ बहुत कम होते हैं।"],"quiz":[["कोफ़ुकु‑जी के मोहरों के साथ मिली पट्टी पर कौन‑सी तारीख़ थी?","1058 (तेनकी 6)","701 (ताइहो 1)","1582 (तेनशो 10)","1868 (मेइजी 1)"],["माना जाता है कि मोहरे वापस रखने का नियम कब बना?","लगभग 16वीं सदी में","लगभग 8वीं सदी में","लगभग 19वीं सदी में","20वीं सदी में"],["पकड़े मोहरे आसानी से दोबारा इस्तेमाल होने का कारण क्या बताया जाता है?","दोनों पक्षों के मोहरे एक रंग के, दिशा से पहचान","मोहरे सोने के थे","बोर्ड में कम खाने थे","मोहरे पासे से चुने जाते थे"]],"kf":["भारत में जन्मे शतरंज का एक रिश्तेदार, जो जापान में पला-बढ़ा; 9×9 की बिसात पर खेला जाता है","सबसे पुराने मोहरे कोफ़ुकु‑जी के पुराने परिसर से 1058 की तारीख़ वाली पट्टी के साथ मिले","पकड़े गए मोहरों को अपने मोहरे की तरह रखना — “हाथ के मोहरे” — शायद 16वीं सदी के आसपास शुरू हुआ"],"more":[{"h":"एक ही रंग, दिशा से पहचान","p":["शतरंज के मोहरे सफ़ेद और काले रंगे होते हैं, पर शोगी के सभी मोहरे लकड़ी के रंग के हैं: पाँच कोनों वाले मोहरे का नुकीला सिरा किस ओर है, इसी से पता चलता है कि वह किसका है। यही आकार पकड़े गए मोहरे को बस घुमाकर फिर बिसात पर रखने देता है।","हर मोहरे पर उसका नाम लिखा होता है, और दुश्मन के इलाक़े में पहुँचकर वह पलटकर “पदोन्नत” हो सकता है। प्यादा पीछे लिखा と बन जाता है और सोने के सेनापति जैसा चलता है। तराशी हुई आकृतियों की जगह लिखे हुए चपटे मोहरे — यह बात शोगी में उसके पूर्वी एशियाई रिश्तेदारों, चीनी शियांगची और कोरियाई जांगी, जैसी ही है।"],"cap":["शोगी के मोहरे दोनों पक्षों के लिए एक ही रंग के होते हैं; नुकीले सिरे की दिशा से पहचाने जाते हैं। दाईं ओर: पलटकर “पदोन्नत” प्यादा (तोकिन)"]},{"h":"विशाल शोगी का दौर","p":["कामाकुरा और मुरोमाची काल से एदो काल तक, मोहरों की क़िस्में और गिनती बढ़ाते हुए बड़ी-बड़ी शोगी बनाई गईं। 12×12 की चू शोगी पूरे एदो काल में ख़ूब खेली गई और आज भी इसके शौक़ीन हैं।","अभिलेख इससे भी आगे जाते हैं: 15×15 की दाई शोगी, 25×25 की ताई शोगी, और 36×36 की बिसात पर 804 मोहरों वाली ताइक्योकु शोगी। फिर भी रोज़ का खेल 9×9 की शो शोगी थी, जिसने हाथ के मोहरों का नियम पाकर आज की शोगी का रूप लिया।"],"cap":["बिसातों के आकार की तुलना (एक कोने से): 9×9 आज की शोगी (40 मोहरे), 12×12 चू शोगी (92), 15×15 दाई शोगी (130), 25×25 ताई शोगी (354), 36×36 ताइक्योकु शोगी (804)"]},{"h":"एदो की शोगी","p":["एदो काल में शोगुनशाही से वेतन पाने वाले शोगी घराने बने; ओहाशी सोकेई को पहला उस्ताद माना जाता है। हर साल सर्वश्रेष्ठ खिलाड़ी शोगुन के सामने “क़िले के मुक़ाबलों” में खेलते थे, जिन्हें बाद में 17 नवंबर को तय किया गया — आज का शोगी दिवस यहीं से आया।","शोगी आम लोगों का भी मनोरंजन था: हारुनोबु के छापे में एक युवा जोड़ा मच्छरदानी के पास खेल रहा है। कलाकृति जैसे त्सुमे-शोगी पहेली-संग्रह भी बने, जैसे इतो कान्जू का ‘शोगी ज़ुको’ (1755)।"],"cap":["सुज़ुकी हारुनोबु का रंगीन काष्ठ-छापा (लगभग 1767–69): मच्छरदानी के पास शोगी खेलते एक युवती और युवक"]}],"tl":[["1058","कोफ़ुकु‑जी के पुराने परिसर के मोहरे (तेंगी 6 वर्ष की पट्टी के साथ मिले)"],["11वीं सदी का मध्य","‘शिनसारुगाकुकी’ में शोगी का नाम"],["कामाकुरा का आरंभ","‘निचूरेकी’ में हेइआन शोगी के मोहरे दर्ज"],["लगभग 16वीं सदी","हाथ के मोहरों का नियम शुरू हुआ माना जाता है"],["1612","कहा जाता है कि ओहाशी सोकेई आदि को शोगुनशाही से वेतन मिला"],["1716","क़िले के मुक़ाबले 17 नवंबर को तय हुए"],["1755","इतो कान्जू की ‘शोगी ज़ुको’"],["1975","17 नवंबर शोगी दिवस बना"]]},"pachisi":{"title":"पचीसी लूडो कैसे बनी","lead":"भारतीय दरबारों में खेला जाने वाला क्रॉस‑आकार का बोर्ड‑खेल नाम बदलकर दुनिया भर के बच्चों के कमरों तक पहुँचा।","s":["भारत में चौपड़ और पचीसी नाम के खेल हैं: चार खिलाड़ी क्रॉस‑आकार के बोर्ड के चारों ओर गोटियाँ चलाते हैं। चौपड़ में लंबे पासे (पासा) और पचीसी में कौड़ियाँ फेंकी जाती हैं। पचीसी का अर्थ है \"पच्चीस\" — कौड़ियों से आने वाला सबसे बड़ा अंक।","देवता भी खेलते थे। 17वीं सदी के अंत की एक चित्रकृति में भगवान शिव और पार्वती बाघ की खाल पर चौपड़ के बोर्ड के पास बैठे हैं।","मुग़ल बादशाह अकबर (16वीं सदी) के नगर फ़तेहपुर सीकरी के एक आँगन के फ़र्श पर आज भी एक विशाल क्रॉस‑आकार का बोर्ड बना है। कहा जाता है कि अकबर रंगीन कपड़े पहने लोगों को गोटी बनाकर खेलता था।","19वीं सदी में यह खेल समंदर पार गया। अमेरिका में यह \"पारचीज़ी\" नाम से बिका और 1874 में ट्रेडमार्क बना। ब्रिटेन में 1890 के दशक में यह \"लूडो\" (लैटिन में \"मैं खेलता हूँ\") नाम से बाज़ार में आया और परिवारों का पसंदीदा बन गया।","लूडो सरल है: एक पासा, और 6 आने पर गोटी बाहर आती है। दूसरे नामों वाले इसके रिश्तेदार पूरी दुनिया में हैं, जैसे स्पेन का पारचीस और जर्मनी का \"मेन्श एर्गेरे डिश निष्ट\" (\"ग़ुस्सा मत हो\")।"],"quiz":[["\"पचीसी\" नाम का अर्थ क्या है?","पच्चीस","राजा का रास्ता","क्रॉस","कौड़ी"],["अकबर के किस नगर में विशाल बोर्ड वाला आँगन आज भी है?","फ़तेहपुर सीकरी","दिल्ली की क़ुतुब मीनार","ताज महल","एलोरा"],["लैटिन में \"लूडो\" का अर्थ क्या है?","मैं खेलता हूँ","मैं जीतता हूँ","मैं दौड़ता हूँ","मैं फेंकता हूँ"]],"kf":["क्रॉस के आकार की भारतीय बिसात पर दौड़ का खेल: दो टीमों में चार खिलाड़ी अपनी गोटियों को पूरा चक्कर लगवाते हैं","नाम का अर्थ है “पच्चीस” — कौड़ियों से आने वाली सबसे बड़ी संख्या","19वीं सदी में यह समंदर पार गया और पारचीज़ी, लूडो जैसे नामों से दुनिया भर में फैला"],"more":[{"h":"क्रॉस और रास्ता","p":["पचीसी की बिसात एक क्रॉस है, जिसकी चार भुजाएँ बीच के ‘चारकोनी’ से निकलती हैं। हर भुजा में 3 × 8 खाने हैं, कुल 96। बिसात अक्सर कपड़े पर कढ़ाई से बनती थी, ताकि उसे लपेटकर रखा जा सके।","गोटियाँ केंद्र से निकलकर अपनी भुजा के बीच वाले स्तंभ से नीचे जाती हैं, घड़ी की उल्टी दिशा में बिसात का एक चक्कर लगाती हैं और बीच वाले स्तंभ से ऊपर चढ़कर केंद्र लौटती हैं। आमने-सामने बैठे खिलाड़ी साथी होते हैं; जब दोनों अपनी चारों गोटियाँ घर ले आएँ, तो टीम जीतती है।"],"cap":["क्रॉस के आकार की बिसात (हर भुजा 3 × 8 खाने)। नीली रेखा एक खिलाड़ी का रास्ता है: अपनी भुजा के बीच से नीचे, घड़ी की उल्टी दिशा में पूरा चक्कर, और फिर बीच से ऊपर केंद्र तक"]},{"h":"कौड़ियों की गिनती","p":["पचीसी में छह कौड़ियाँ फेंकी जाती हैं, और जितनी मुँह ऊपर गिरें, उससे चाल तय होती है। दो से छह हों तो उतने खाने; पर एक हो तो 10, और एक भी न हो तो 25 खाने।","64 में 1 बार आने वाला 25 सबसे दुर्लभ और सबसे बड़ा दाँव है — इसी से खेल का नाम पड़ा। 6, 10 या 25 आने पर एक और बार फेंकने को मिलता है। चौपड़ में इसके बजाय 1, 2, 5 और 6 अंकों वाले तीन लंबे पासे फेंके जाते हैं।"],"cap":["छह कौड़ियों में से कितनी मुँह ऊपर गिरीं (ऊपर की पंक्ति) और तब कितने खाने चलना है (नीचे की पंक्ति)। डंडों की ऊँचाई बताती है कि हर कौड़ी के दोनों ओर बराबर गिरने पर यह कितनी बार आता है"]},{"h":"नए नाम, नए देश","p":["भारत में रहे अंग्रेज़ों के ज़रिए यह खेल 19वीं सदी में यूरोप और अमेरिका पहुँचा। अमेरिका में यह पारचीज़ी ट्रेडमार्क बना; ब्रिटेन में 1896 में लूडो का पेटेंट हुआ — आसान नियमों और कौड़ियों की जगह एक घनाकार पासे के साथ।","जर्मनी में 1914 में ‘मेन्श एर्गेरे दिश निष्ट’ (“नाराज़ मत हो”) आया, और स्पेन में पारचीस खेला जाता है। देश-देश में नाम और ब्यौरे बदलते हैं, पर ढाँचा वही है: क्रॉस का चक्कर लगाकर घर लौटना।"],"cap":[]}],"tl":[["16वीं सदी","अकबर की फ़तेहपुर सीकरी में विशाल क्रॉस-बिसात वाला आँगन बना"],["17वीं–18वीं सदी","भारतीय लघुचित्रों में चौपड़ के इर्द-गिर्द बैठे लोग अक्सर दिखते हैं"],["1694–95","देवीदास ने चौपड़ खेलते शिव और पार्वती को चित्रित किया"],["1874","अमेरिका में पारचीज़ी ट्रेडमार्क बना"],["1896","ब्रिटेन में लूडो का पेटेंट हुआ"],["1914","जर्मनी में ‘मेन्श एर्गेरे दिश निष्ट’ बिक्री में आया"]]},"go":{"title":"1300 साल पुराना गो बोर्ड क्या बताता है","lead":"शोसोइन के गो बोर्ड पर आज जैसी 19 रेखाएँ हैं — और आज से अलग, 17 फूल‑चिह्न।","s":["गो प्राचीन चीन में जन्मा। किंवदंती है कि ज्ञानी राजा याओ ने इसे अपने बेटे को सिखाने के लिए बनाया। ईसा पूर्व की पुस्तक \"मेंगज़ी\" में इस खेल के उस्ताद यी चिउ का नाम आता है।","माना जाता है कि बोर्ड का आकार समय के साथ बदला: शुरुआती दौर में 17 रेखाओं वाले बोर्ड भी चलते थे, बाद में आज का 19 रेखाओं वाला बोर्ड फैला।","गो जापान कब पहुँचा, साफ़ नहीं, पर नारा काल में यह खेला जाता था। भिक्षुओं और भिक्षुणियों के नियम संगीत और जुए पर रोक लगाते थे, पर गो और कोतो की छूट देते थे — सुगोरोकु से बिल्कुल अलग बरताव।","शोसोइन का जड़ाऊ गो बोर्ड सम्राट शोमु से जुड़े ख़ज़ाने के रूप में चला आया है। इसमें आज जैसी 19 रेखाएँ हैं, पर जहाँ आज के बोर्ड पर 9 तारा‑बिंदु होते हैं, वहाँ इसमें 17 फूल‑चिह्न हैं। इसकी दोनों दराज़ें जुड़ी हैं: एक खींचो तो दूसरी भी निकल आती है। शोसोइन में लाल और गहरे नीले रंग में रँगे हाथीदाँत के, पक्षियों की नक़्क़ाशी वाले गो पत्थर भी हैं।","हेइआन काल की \"गेंजी की कथा\" में गो खेलने के दृश्य हैं। एदो काल में होन’इम्बो जैसे घरानों ने शोगुनशाही की सेवा की, और गो पेशेवर खिलाड़ियों के हुनर की होड़ वाली कला बन गया।"],"quiz":[["शोसोइन के गो बोर्ड में कितनी रेखाएँ हैं?","19","17","13","9"],["भिक्षुओं और भिक्षुणियों को किस खेल की छूट थी?","गो और कोतो","सुगोरोकु","जुआ","केमारी"],["शोसोइन बोर्ड पर तारा‑बिंदुओं की जगह कितने फूल‑चिह्न हैं?","17","9","4","25"]],"kf":["रेखाओं के मिलन-बिंदुओं पर काले और सफ़ेद पत्थर रखकर ज़्यादा इलाक़ा घेरने की होड़ — प्राचीन चीन में जन्मा खेल","17 रेखाओं वाले बोर्डों के दौर के बाद 19 रेखाएँ आईं; शोसोइन में 8वीं सदी का 19 रेखाओं वाला बोर्ड है","एदो जापान में गो घराने शोगुनशाही की सेवा में थे; 21वीं सदी में एक AI ने दुनिया के सबसे अच्छे खिलाड़ी को हराया"],"more":[{"h":"घेरो, पकड़ो, इलाक़ा बढ़ाओ","p":["गो में काला और सफ़ेद बारी-बारी से रेखाओं के मिलन-बिंदुओं पर पत्थर रखते हैं। रखा गया पत्थर फिर नहीं हिलता। जब किसी पत्थर (या समूह) के पास के सारे ख़ाली बिंदु विरोधी के पत्थरों से भर जाएँ, तो वह पकड़ा जाता है और बोर्ड से हटा दिया जाता है।","आख़िर में घेरा गया इलाक़ा और पकड़े गए पत्थर मिलाकर जिसका ज़्यादा हो, वह जीतता है। नियम कम हैं, पर बोर्ड बड़ा है: 19 रेखाओं वाले बोर्ड पर संभव स्थितियों की संख्या लगभग 10 की घात 170 आँकी गई है।"],"cap":["पत्थर पकड़ने का तरीक़ा। बाएँ: काले पत्थर के पास चार ख़ाली बिंदु (लाल)। बीच में: सफ़ेद ने तीन ओर से घेरा, एक बचा। दाएँ: आख़िरी भी बंद, काला पत्थर पकड़ा गया"]},{"h":"17 रेखाओं से 19 तक","p":["चीन के हबेई प्रांत के वांगदू में पूर्वी हान काल की एक क़ब्र से 17 रेखाओं वाला पत्थर का गो बोर्ड मिला है। वहीं लगभग 6वीं सदी का माना जाने वाला दुनहुआंग का ‘गो ग्रंथ’ 361 बिंदुओं, यानी 19 रेखाओं वाले बोर्ड का वर्णन करता है। लगता है इस बीच बोर्ड बड़ा हुआ।","शोसोइन का बोर्ड 19 रेखाओं का है, पर आज के नौ तारा-बिंदुओं की जगह उस पर 17 जगह फूलों के निशान हैं। 289 से 361 बिंदु होने भर से खेल कहीं ज़्यादा गहरा हो गया।"],"cap":["17 और 19 रेखाओं वाले बोर्डों की बिंदुओं की संख्या से तुलना। आज के बोर्ड के नौ काले बिंदु “तारा-बिंदु” हैं"]},{"h":"अमरों का गो, उस्तादों का गो","p":["एक चीनी कथा में एक लकड़हारा पहाड़ पर अमरों को गो खेलते देखता रहता है — और होश आने पर पाता है कि इतने बरस बीत गए कि उसकी कुल्हाड़ी का हत्था सड़ चुका है। अमरों के खेल के रूप में गो तश्तरियों और चित्रों का प्रिय विषय रहा।","एदो जापान में होनइम्बो जैसे गो घराने शोगुनशाही से वेतन पाते थे, और गो एक कला की तरह निखरा। 1938 में होनइम्बो शूसाई का विदाई मुक़ाबला कावाबाता यासुनारी के उपन्यास ‘द मास्टर ऑफ़ गो’ का आधार बना। 2016 में AI अल्फ़ागो ने दुनिया के शीर्ष खिलाड़ी ली सेडोल को 4–1 से हराकर दुनिया को चौंका दिया।"],"cap":["गो खेलते अमरों वाली नक़्क़ाशीदार लाख की तश्तरी (मिंग वंश, शुआनदे काल, 1425–36)"]}],"tl":[["लगभग चौथी सदी ई.पू.","मेंशियस में गो उस्ताद यी चिउ का नाम"],["पूर्वी हान","वांगदू की क़ब्र में 17 रेखाओं वाला पत्थर का बोर्ड रखा गया"],["लगभग 6वीं सदी","दुनहुआंग का ‘गो ग्रंथ’ 19 रेखाएँ और 361 बिंदु बताता है"],["8वीं सदी","शोसोइन का जड़ाऊ चंदन का गो बोर्ड"],["1612","कहा जाता है कि होनइम्बो सान्सा आदि को शोगुनशाही से वेतन मिला"],["1938","होनइम्बो शूसाई का विदाई मुक़ाबला, बाद में कावाबाता का उपन्यास"],["2016","अल्फ़ागो ने ली सेडोल को 4–1 से हराया"]]},"draughts":{"title":"चेकर्स (ड्राफ़्ट्स) कैसे जन्मा","lead":"एक अरबी बोर्ड‑खेल, शतरंज का बोर्ड और शतरंज का वज़ीर — माना जाता है कि इन तीनों के मेल से चेकर्स बना।","s":["चेकर्स का पूर्वज अल्केर्के माना जाता है, जो रेखाओं से जुड़े 5×5 बिंदुओं के जाल पर खेला जाता था। अरबी में इसे क़िर्क़ कहते थे और 10वीं सदी की \"गीतों की किताब\" में इसका नाम है। मूर इसे स्पेन ले गए, और इसके नियम 13वीं सदी में कास्तील के राजा अल्फ़ोंसो दसवें की बनवाई \"खेलों की किताब\" में दर्ज हैं।","लगभग 12वीं सदी में, शायद दक्षिणी फ़्रांस में, अल्केर्के की गोटियाँ शतरंज के बोर्ड पर चलाई जाने लगीं। यही \"फ़्येर्ज\" था। गोटियों को उस समय के शतरंज के वज़ीर \"फ़र्ज़\" का ही नाम मिला।","दूर के किनारे तक पहुँचकर गोटी का ताक़तवर होना — पदोन्नति — 13वीं सदी के मध्य के एक इतिहास‑ग्रंथ में पहले से दर्ज है। शायद यह शतरंज के उस प्यादे से लिया गया जो वज़ीर बन जाता है।","बड़ा बदलाव लगभग 1535 में फ़्रांस में आया: अनिवार्य मारने का नियम जुड़ा — अगर मार सकते हो, तो मारना ही होगा — और खेल \"ज़बरन खेल\" (jeu forcé) कहलाया। अंग्रेज़ी ड्राफ़्ट्स और अमेरिकी चेकर्स इसी से निकले।","बिना अनिवार्य मारने वाला पुराना खेल \"महिलाओं का नरम खेल\" कहलाकर बचा रहा और बाद में 10×10 बोर्ड के अंतरराष्ट्रीय खेल तक पहुँचा। एक ही पूर्वज से कई \"रानी के खेल\" फूटे।"],"quiz":[["चेकर्स का पूर्वज कौन‑सा खेल माना जाता है?","अल्केर्के","सेनेट","लिउबो","मनकाला"],["अनिवार्य मारने का नियम कब और कहाँ जुड़ा?","लगभग 1535 में फ़्रांस में","10वीं सदी में बग़दाद में","1900 में अमेरिका में","8वीं सदी में जापान में"],["फ़्येर्ज की गोटियों को किसका नाम मिला?","शतरंज के वज़ीर (फ़र्ज़) का","शतरंज के राजा का","पासों का","घोड़े का"]],"kf":["अरबी खेल अल्केर्के की गोटियाँ जब शतरंज के बोर्ड पर आईं, तब यह खेल जन्मा","गोटियाँ तिरछी चलती हैं और कूदकर मारती हैं; आख़िरी पंक्ति तक पहुँचकर राजा बनती हैं","लगभग 1535 में ‘मारना ज़रूरी’ का नियम जुड़ा, और 2007 में खेल (8 × 8) हल हो गया"],"more":[{"h":"बिंदु और रेखाओं से शतरंज के बोर्ड तक","p":["अल्केर्के का बोर्ड 5 × 5 जाल में रेखाओं से जुड़े 25 बिंदुओं का होता है। दोनों ओर 12-12 गोटियाँ रखी जाती हैं और खेल बीच के एकमात्र ख़ाली बिंदु से शुरू होता है। गोटियाँ रेखाओं पर चलती हैं और पास की विरोधी गोटी के ऊपर से कूदकर उसे मारती हैं।","जब गोटियाँ शतरंज के बोर्ड पर आईं, तो सिर्फ़ एक रंग के खाने इस्तेमाल होने लगे। 8 × 8 बोर्ड पर 32 गहरे खाने होते हैं; दोनों ओर की पहली तीन पंक्तियाँ भरें तो हर पक्ष की 12 गोटियाँ बनती हैं — ठीक अल्केर्के जितनी।"],"cap":["अल्केर्के का बोर्ड और शुरुआती जमावट: सीधी और तिरछी रेखाओं से जुड़े 5 × 5 बिंदु, हर ओर 12 गोटियाँ, सिर्फ़ बीच ख़ाली"]},{"h":"कूदो, मारो, राजा बनो","p":["गोटियाँ तिरछे आगे एक खाना चलती हैं, और पास की विरोधी गोटी के पीछे का खाना ख़ाली हो तो उसके ऊपर से कूदकर उसे मारती हैं। उसके बाद फिर मार सकें तो कूदती रहती हैं। आज के नियम में मार सकते हो तो मारना ही पड़ता है।","आख़िरी पंक्ति तक पहुँची गोटी पर दूसरी गोटी रख दी जाती है और वह राजा बन जाती है; अब वह पीछे भी चल सकती है। 10 × 10 बोर्ड वाले अंतरराष्ट्रीय खेल में राजा तिरछी रेखा पर कितनी भी दूर जा सकता है, जिससे अंत का खेल पूरी तरह बदल जाता है।"],"cap":["मारना और राजा बनना। लाल गोटी लगातार दो सफ़ेद गोटियों के ऊपर से कूदकर उन्हें मारती है (×), फिर आख़िरी पंक्ति तक पहुँचकर दो गोटियों वाला राजा बनती है"]},{"h":"हल हुआ खेल, फैलता परिवार","p":["कनाडा में जोनाथन शेफ़र और उनकी टीम ने चिनूक नाम का प्रोग्राम बनाया। 1992 में उसने मैरियन टिंसली से मुक़ाबला किया, जो 40 से ज़्यादा बरसों में मुश्किल से कोई बाज़ी हारे थे, और टिंसली जीते। टीम गणना करती रही और 2007 में साबित किया कि दोनों पक्ष बिना चूक खेलें तो खेल (8 × 8) बराबरी पर ख़त्म होता है।","इस बीच उसी पूर्वज का परिवार दुनिया भर में ज़िंदा है: 10 × 10 का अंतरराष्ट्रीय ड्राफ़्ट्स, रूसी शाश्की, सीधी चाल वाला तुर्की दामा, 12 × 12 का कनाडाई चेकर्स — और हर देश में प्रतियोगिताएँ होती हैं।"],"cap":[]}],"tl":[["10वीं सदी","‘गीतों की किताब’ में क़िर्क़ (अल्केर्के) का नाम"],["लगभग 12वीं सदी","शायद दक्षिणी फ़्रांस में फ़ियर्ज का जन्म"],["1283","अल्फ़ोंसो दशम की ‘खेलों की किताब’ में अल्केर्के का वर्णन"],["लगभग 1535","फ़्रांस में ‘मारना ज़रूरी’ नियम जुड़ा"],["1547","स्पेन में तोरकेमादा ने ड्राफ़्ट्स पर पहली किताब छापी"],["18वीं सदी","फ़्रांस और नीदरलैंड में 10 × 10 बोर्ड फैला"],["1992","टिंसली ने चिनूक प्रोग्राम को हराया"],["2007","साबित हुआ कि बिना चूक खेलने पर खेल (8 × 8) बराबरी पर ख़त्म होता है"]]},"reversi":{"title":"रिवर्सी और ओथेलो: आविष्कारक कौन?","lead":"काले‑सफ़ेद गोटियों को घेरकर पलटने का खेल — और 19वीं सदी के इंग्लैंड के दो लोग, जो इस पर दावा करते रहे।","s":["1880 के दशक के लंदन में दो अंग्रेज़, लुईस वॉटरमैन और जॉन डब्ल्यू. मॉलेट, दोनों ख़ुद को इस खेल का आविष्कारक बताते और दूसरे को धोखेबाज़ कहते थे।","मॉलेट का खेल \"एनेक्सेशन\" क्रॉस‑आकार के बोर्ड पर खेला जाता था। वॉटरमैन की \"रिवर्सी\" साधारण 8×8 बोर्ड पर, और आज उसी का रूप बचा है। नाम का झगड़ा अदालत तक भी गया।","रिवर्सी यूरोप में फैली; 1893 में जर्मन कंपनी रावेन्सबर्गर ने इसे अपने शुरुआती उत्पादों में निकाला। जापान में मेइजी काल की किताबों में इसका वर्णन हुआ और इसे \"गेनपेई‑गो\" भी कहा गया।","पर लोकप्रियता टिकी नहीं। 1971 में गोरो हासेगावा ने शुरुआती चार गोटियाँ बीच में आड़ी‑तिरछी रखकर शुरुआत तय की और इसे \"ओथेलो\" नाम से निकाला; जापान में यह ज़ोरों पर चल पड़ा।","कहा जाता है कि नाम शेक्सपियर के नाटक से लिया गया: श्याम वर्ण सेनापति ओथेलो और उसकी गोरी पत्नी डेज़डेमोना, काली और सफ़ेद गोटियों की याद दिलाते हैं। आज के टूर्नामेंट नियम ओथेलो के ही हैं।"],"quiz":[["रिवर्सी पर झगड़ने वाले दोनों लोग कब और कहाँ के थे?","19वीं सदी का इंग्लैंड","18वीं सदी का फ़्रांस","20वीं सदी का जापान","16वीं सदी का इटली"],["मॉलेट के एनेक्सेशन का बोर्ड किस आकार का था?","क्रॉस","गोल","त्रिकोण","8×8 वर्ग"],["1971 में ओथेलो किसने निकाला?","गोरो हासेगावा","होनिम्बो शूसाकु","लुईस वॉटरमैन","रावेन्सबर्गर"]],"kf":["विरोधी की गोटियों को अपनी गोटियों के बीच घेरकर पलटो; अंत में जिसकी गोटियाँ ज़्यादा, वह जीते","1880 के दशक के लंदन में दो अंग्रेज़ों में आविष्कारक होने पर झगड़ा हुआ","1970 के दशक में जापान में ‘ओथेलो’ नाम से छा गया, और 2023 में दिखाया गया कि बिना चूक खेलें तो बराबरी"],"more":[{"h":"घेरो और पलटो","p":["गोटी सिर्फ़ वहीं रखी जा सकती है जहाँ वह विरोधी की गोटियों की एक पंक्ति को अपने और अपनी किसी दूसरी गोटी के बीच घेर ले। पंक्तियाँ आठ दिशाओं में जाती हैं — आड़ी, खड़ी और तिरछी — और एक चाल कई दिशाएँ एक साथ घेर सकती है। घिरी हुई सारी गोटियाँ आपके रंग में पलट जाती हैं।","कोई चाल न हो तो बारी छोड़ते हैं; जब दोनों में से कोई न चल सके, खेल ख़त्म। कोनों की गोटियाँ कभी घेरी नहीं जा सकतीं, इसलिए कोना लेना बड़ा फ़ायदा है। मज़बूत खिलाड़ी अभी की गिनती से ज़्यादा इस पर ध्यान देते हैं कि विरोधी के खेलने की जगहें कम हों।"],"cap":["गोटियाँ कैसे पलटती हैं। लाल घेरे वाले खाने पर रखी काली गोटी तीन दिशाओं — आड़ी, खड़ी और तिरछी — में सफ़ेद गोटियों को घेरती है, और सुनहरे किनारे वाली सातों गोटियाँ काली हो जाती हैं"]},{"h":"पहली चार गोटियाँ","p":["शुरुआती रिवर्सी में दोनों खिलाड़ी बारी-बारी से पहली चार गोटियाँ बीच के चार खानों में रखते थे, इसलिए शुरुआत अगल-बगल भी हो सकती थी और आड़ी-तिरछी भी।","ओथेलो ने आड़ी-तिरछी शुरुआत तय कर दी। पहली चाल से ही दोनों रंग आसानी से घेरे जा सकते हैं, सो मुक़ाबला तुरंत शुरू हो जाता है। आज की विश्व प्रतियोगिताएँ इसी स्थिति से शुरू होती हैं।"],"cap":["पहली चार गोटियाँ। बाएँ: पुराने रिवर्सी की एक संभव शुरुआत (एक ही रंग अगल-बगल)। दाएँ: ओथेलो की तय की हुई आड़ी-तिरछी शुरुआत"]},{"h":"इंसान और कंप्यूटर","p":["ओथेलो जापान से दुनिया भर में फैला, और 1977 में टोक्यो में पहली विश्व ओथेलो चैंपियनशिप हुई। नियम सरल हैं, इसलिए फ़र्क़ गणना की गहराई से पड़ता है; शीर्ष खिलाड़ी दर्जनों चालें आगे देखते हैं।","1997 में लॉजिस्टेलो प्रोग्राम ने विश्व चैंपियन ताकेशी मुराकामी से छह बाज़ियाँ खेलीं और सभी जीतीं। 2023 में गणनाओं ने दिखाया कि 8 × 8 ओथेलो दोनों पक्षों के बिना चूक खेलने पर बराबरी पर ख़त्म होता है।"],"cap":[]}],"tl":[["1880 का दशक","लंदन में वॉटरमैन और मॉलेट आविष्कार पर झगड़े"],["1893","जर्मनी में रेवेन्सबर्गर ने रिवर्सी निकाला"],["मेइजी काल","जापानी किताबों में ‘गेनपेई-गो’ नाम से परिचय"],["1973","जापान में ओथेलो के सेट बिकने लगे"],["1977","टोक्यो में पहली विश्व ओथेलो चैंपियनशिप"],["1997","लॉजिस्टेलो ने विश्व चैंपियन ताकेशी मुराकामी को 6–0 से हराया"],["2023","दिखाया गया कि 8 × 8 ओथेलो बिना चूक खेलने पर बराबरी है"]]},"mancala":{"title":"मनकाला कहाँ जन्मा?","lead":"गड्ढे‑दर‑गड्ढे बीज बोने की तरह पत्थर बाँटने का खेल, जो अफ़्रीका और एशिया में सैकड़ों नामों से खेला जाता है।","s":["मनकाला उन खेलों के परिवार का नाम है जिनमें एक गड्ढे से पत्थर या बीज उठाकर आगे के गड्ढों में एक‑एक करके बोए जाते हैं। कहा जाता है कि यह शब्द अरबी \"नक़ला\" (हटाना) से आया है।","नाम और नियम जगह‑जगह बदलते हैं — पश्चिम अफ़्रीका में ओवारे, पूर्वी अफ़्रीका में बाओ, तुर्की में मंगाला, दक्षिण‑पूर्व एशिया में चोंगकाक, और सैकड़ों और — दो या चार पंक्तियाँ, गड्ढे कितने भी।","इसे अक्सर बहुत पुराना बताया जाता है, पर पक्के सबूत अपेक्षा से नए हैं। अब तक पक्की तारीख़ वाले सबसे पुराने बोर्ड प्राचीन अक्सूम राज्य के स्थलों — मतारा और येहा (इरित्रिया और इथियोपिया) — से मिले लगभग 6वीं‑7वीं सदी के मिट्टी और पत्थर के बोर्ड माने जाते हैं।","इससे पुराने उदाहरण भी सुझाए गए हैं, पर यह तय नहीं कि वे छेदों की पंक्तियाँ सचमुच मनकाला के लिए थीं, और विद्वान बँटे हुए हैं। एक प्रबल मत है कि खेल अक्सूम से अरब और अफ़्रीका के भीतरी हिस्सों तक फैला।","खेलने के तरीक़े के पूरे विवरण लगभग 17वीं सदी में ही मिलते हैं। एटलस में आप मनकाला को ओवारे और मंगाला सहित आठ नियमों से खेल सकते हैं।"],"quiz":[["\"मनकाला\" जिस अरबी शब्द से आया, उसका अर्थ क्या है?","हटाना","बीज","गड्ढा","राजा"],["पक्की तारीख़ वाले सबसे पुराने मनकाला बोर्ड कहाँ मिले?","प्राचीन अक्सूम राज्य के स्थलों में (इथियोपिया और इरित्रिया)","रोम के कोलोसियम में","चीन की महान दीवार पर","स्टोनहेंज में"],["पश्चिम अफ़्रीका में कौन‑सा मनकाला खेला जाता है?","ओवारे","लिउबो","तफ़्ल","पचीसी"]],"kf":["“बुवाई” वाले खेलों का परिवार: एक गड्ढे के सारे बीज उठाकर अगले गड्ढों में एक-एक डालते जाते हैं","पक्की तारीख़ वाले सबसे पुराने बोर्ड प्राचीन अक्सुम राज्य के हैं, लगभग 6वीं–7वीं सदी के","दो पंक्तियाँ या चार, भंडार के साथ या बिना — इलाक़े-इलाक़े में बोर्ड और नियम बदलते हैं"],"more":[{"h":"बुवाई","p":["मनकाला में अपनी ओर का एक गड्ढा चुनकर उसके सारे बीज निकालते हैं और अगले गड्ढों में एक-एक डालते जाते हैं। खेत में बीज छिड़कने जैसी इस चाल को बुवाई कहते हैं।","पश्चिम अफ़्रीका का ओवारे 48 बीजों से शुरू होता है — 12 गड्ढों में चार-चार। आख़िरी बीज से विरोधी के गड्ढे में दो या तीन हो जाएँ, तो वे आपके। बुवाई कहाँ ख़त्म होगी, यह पहले से गिन लेना ही सब कुछ है। ओवारे अटलांटिक पार कर कैरिबियाई द्वीपों तक पहुँचा।"],"cap":["ओवारे में बुवाई। सुनहरे घेरे वाले गड्ढे के तीन बीज घड़ी की उल्टी दिशा में एक-एक कर डाले जाते हैं; आख़िरी बीज विरोधी के गड्ढे में ठीक 3 कर देता है, तो वे 3 ले लिए जाते हैं (लाल घेरा)"]},{"h":"दो पंक्तियाँ और चार","p":["मनकाला के बोर्ड मोटे तौर पर दो पंक्ति और चार पंक्ति वाले होते हैं। दो पंक्ति वाले पश्चिम अफ़्रीका और एशिया में आम हैं; चार पंक्ति वाले पूर्वी अफ़्रीका से दक्षिणी अफ़्रीका तक फैले हैं। तंज़ानिया का बाओ 4 पंक्ति × 8 गड्ढों का है; स्वाहिली में इसके नाम का मतलब ही “बोर्ड” है।","दक्षिण-पूर्व एशिया के चोंगकाक और सुंगका जैसे कुछ बोर्डों के दोनों सिरों पर पकड़े गए बीजों के लिए बड़ा गड्ढा — भंडार — होता है। 20वीं सदी में अमेरिका में जन्मा कलाह भी भंडार वाला दो पंक्ति का खेल है; 2000 में गणना से पता चला कि छह गड्ढों और चार-चार बीजों वाला कलाह हमेशा पहला खिलाड़ी जीतता है।"],"cap":["मनकाला बोर्डों के उदाहरण: 2 पंक्ति × 6 (ओवारे आदि), दोनों सिरों पर भंडार वाला 2 पंक्ति × 7 (दक्षिण-पूर्व एशिया का चोंगकाक आदि), 4 पंक्ति × 8 (पूर्वी अफ़्रीका का बाओ आदि)"]},{"h":"इसे दर्ज करने वाले","p":["मनकाला का विस्तार से वर्णन करने वाले पहले यूरोपीय विद्वान आम तौर पर इंग्लैंड के थॉमस हाइड माने जाते हैं। ‘दे लूदिस ओरिएंतालिबुस’ (1694) में उन्होंने इसका अरबी नाम और खेलने का तरीक़ा दिया।","1836 में एडवर्ड डब्ल्यू. लेन ने क़ाहिरा के रोज़मर्रा जीवन के वर्णन में क़हवाख़ानों में खेले जाने वाले “मनकाला” को दर्ज किया। आज शोधकर्ताओं ने दुनिया भर से खेल जुटाए हैं, और दर्ज नियमों की गिनती सैकड़ों में है।"],"cap":[]}],"tl":[["6वीं–7वीं सदी","अक्सुम के स्थलों से पक्की तारीख़ वाले सबसे पुराने बोर्ड"],["1694","थॉमस हाइड ने ‘दे लूदिस ओरिएंतालिबुस’ में मनकाला का वर्णन किया"],["18वीं–19वीं सदी","ओवारे आदि अटलांटिक पार कर कैरिबियन पहुँचे"],["1836","ई. डब्ल्यू. लेन ने क़ाहिरा का मनकाला दर्ज किया"],["20वीं सदी का मध्य","भंडार वाला दो पंक्ति का कलाह अमेरिका में बिकने लगा"],["2000","गणना: छह गड्ढे, चार बीज वाले कलाह में पहला खिलाड़ी जीतता है"]]},"morris":{"title":"नाइन मेन्स मॉरिस हर जगह है","lead":"मंदिर की छत, वाइकिंग जहाज़, गिरजाघर की पत्थर की बेंच — जहाँ भी लोग साथ बैठे, वहाँ इसकी रेखाएँ खुदी मिलीं।","s":["नाइन मेन्स मॉरिस में हर खिलाड़ी तीन एक‑दूसरे में बने वर्गों के 24 बिंदुओं पर नौ‑नौ गोटियाँ रखता है; तीन एक पंक्ति में — \"चक्की\" — बनें तो विरोधी की एक गोटी हटाई जाती है। अंग्रेज़ी नाम \"मॉरिस\" का नृत्य से कोई संबंध नहीं; कहा जाता है कि यह लैटिन शब्द merellus यानी \"गोटी\" से आया।","मिस्र के कुर्ना मंदिर की छत की पटिया पर खुदे बोर्ड को अक्सर लगभग 1400 ई.पू. का सबसे पुराना उदाहरण बताया जाता है। पर शोधकर्ता फ़्रीडरिख़ बर्गर ने उन्हीं खुदाइयों में कॉप्टिक क्रॉस देखे और कहा कि इनकी तारीख़ तय नहीं की जा सकती। पक्के उदाहरण रोमन काल से शुरू होते हैं।","नॉर्वे के लगभग 900 ई. के गोकस्ताद जहाज़ में डेक के एक तख़्ते पर यह बोर्ड खुदा है। इंग्लैंड में कैंटरबरी, सैलिसबरी जैसे गिरजाघरों के गलियारों की पत्थर की बेंचों पर भी बोर्ड बचे हैं।","1283 की अल्फ़ोंसो दसवें की \"खेलों की किताब\" में इसे पासों से खेलते हुए भी दिखाया गया है। शेक्सपियर ने \"ए मिडसमर नाइट्स ड्रीम\" में लिखा कि बारिश ने \"नाइन मेन्स मॉरिस\" को कीचड़ से भर दिया — गाँव की घास में खोदा गया बोर्ड।","1996 में जर्मनी के राल्फ़ गैसर ने कंप्यूटर से सारी स्थितियाँ जाँचकर साबित किया कि दोनों पक्ष सबसे अच्छा खेलें तो खेल बराबरी पर ख़त्म होता है। फिर भी दो लोगों के बीच यह आज भी बढ़िया खेल है।"],"quiz":[["\"मॉरिस\" नाम कहाँ से आया माना जाता है?","लैटिन के \"गोटी\" शब्द से","एक अंग्रेज़ी नृत्य से","किसी व्यक्ति के नाम से","एक जहाज़ के नाम से"],["कुर्ना मंदिर के बोर्डों के बारे में शोधकर्ताओं ने क्या कहा?","उनकी तारीख़ तय नहीं हो सकती","वे सोने के हैं","वे चीन से आए","वे एक सम्राट के थे"],["1996 में कंप्यूटर ने क्या साबित किया?","सबसे अच्छे खेल में बराबरी","पहला खिलाड़ी हमेशा जीतता है","दूसरा हमेशा जीतता है","आठ गोटियाँ काफ़ी हैं"]],"kf":["तीन एक-दूसरे में बने वर्गों के 24 बिंदुओं पर नौ-नौ गोटियाँ; तीन एक पंक्ति में आएँ तो विरोधी की एक गोटी हटती है","रोमन काल से इसका बोर्ड वहाँ खोदा गया जहाँ लोग जुटते थे — जहाज़ों के डेक, गिरजाघरों की बेंचें","1996 में कंप्यूटर ने सारी स्थितियाँ जाँचीं: बिना चूक खेलें तो बराबरी"],"more":[{"h":"रखो, चलो, उड़ो","p":["खेल तीन चरणों में चलता है। पहले दोनों बारी-बारी से अपनी नौ गोटियाँ ख़ाली बिंदुओं पर रखते हैं। सब रख लेने के बाद, हर बार एक गोटी रेखा के साथ पास के ख़ाली बिंदु पर चलाई जाती है।","रेखा पर अपनी तीन गोटियाँ एक पंक्ति में आएँ तो ‘मिल’ बनती है और विरोधी की एक गोटी बोर्ड से हटा सकते हैं। एक आम नियम में, जिसके पास तीन गोटियाँ बचें, वह किसी भी ख़ाली बिंदु पर ‘उड़’ सकता है। जिसके पास दो गोटियाँ बचें या जो चल न सके, वह हारता है।"],"cap":["नाइन मेन्स मॉरिस का बोर्ड। सफ़ेद ने बाहरी किनारे पर तीन गोटियों की ‘मिल’ बनाई (सुनहरा), इसलिए वह एक काली गोटी हटा सकता है (लाल क्रॉस)"]},{"h":"तीन से बारह गोटियों तक","p":["यह परिवार गोटियों की संख्या से जाना जाता है। तीन-तीन गोटियों वाला थ्री मेन्स मॉरिस छोटा बोर्ड है, ज़ीरो-काटा जैसा। छह-छह वाला सिक्स मेन्स मॉरिस दो एक-दूसरे में बने वर्गों का बोर्ड इस्तेमाल करता है।","बारह-बारह वाला ट्वेल्व मेन्स मॉरिस, नाइन मेन्स के बोर्ड में तिरछी रेखाएँ जोड़ता है। दक्षिण अफ़्रीका में इसे मोराबाराबा कहते हैं; कहा जाता है कि मवेशी चराने वाले लड़के इसे ज़मीन पर बनाते थे, और आज इसकी प्रतियोगिताएँ भी होती हैं।"],"cap":["बोर्डों की तुलना। संख्या हर खिलाड़ी की गोटियाँ है: थ्री, सिक्स, नाइन और ट्वेल्व मेन्स मॉरिस"]},{"h":"शतरंज विजेता और कंप्यूटर","p":["विश्व शतरंज विजेता इमैनुअल लास्कर भी इस खेल के दीवाने थे। अपनी किताब ‘ब्रेटश्पीले डेर फ़ोल्कर’ (1931) में उन्होंने दस-दस गोटियों वाला रूप सुझाया, जिसमें सारी गोटियाँ रखने से पहले भी चल सकते हैं।","1996 में स्विट्ज़रलैंड के राल्फ़ गैसर ने अंत की सारी स्थितियों की पूरी तालिकाओं को शुरुआत से की गई खोज के साथ जोड़कर दिखाया कि दोनों पक्ष बिना चूक खेलें तो नाइन मेन्स मॉरिस बराबरी पर ख़त्म होता है। बोर्ड पर सिर्फ़ 24 बिंदु हैं, पर स्थितियाँ अरबों में हैं।"],"cap":[]}],"tl":[["रोमन काल","साम्राज्य भर में पत्थरों पर बोर्ड खोदे गए (पहले पक्के उदाहरण)"],["लगभग 900","नॉर्वे के गोकस्ताद जहाज़ के डेक के तख़्ते पर बोर्ड खोदा गया"],["1283","अल्फ़ोंसो दशम की ‘खेलों की किताब’ में मॉरिस का चित्र"],["मध्यकाल","इंग्लैंड के गिरजाघरों के गलियारों की बेंचों पर बोर्ड"],["1590 का दशक","शेक्सपियर के ‘ए मिडसमर नाइट्स ड्रीम’ में कीचड़ भरे बोर्ड का ज़िक्र"],["1931","लास्कर ने ‘ब्रेटश्पीले डेर फ़ोल्कर’ में नया रूप सुझाया"],["1996","गैसर ने सिद्ध किया कि बिना चूक खेलने पर बराबरी"]]},"patolli":{"title":"पातोल्ली, एज़्टेकों की बीन्स‑दौड़","lead":"क्रॉस‑आकार का बोर्ड और पासों की जगह बीन्स — ऐसा जुए वाला खेल कि स्पेनियों ने इस पर रोक लगा दी।","s":["पातोल्ली मेक्सिको के एज़्टेक लोगों का दौड़‑खेल था। इसके नाम का अर्थ है बीन्स: एक तरफ़ निशान या छेद वाली पाँच लाल बीन्स फेंकी जाती थीं और जितने निशान ऊपर आते, उतना चटाई या ज़मीन पर बने क्रॉस‑आकार के रास्ते पर आगे बढ़ते थे।","16वीं सदी में इस इलाक़े का वर्णन करने वाले दिएगो दुरान ने लिखा कि खिलाड़ी फेंकने से पहले धूप जलाते, बीन्स से प्रार्थना करते और खेलों के देवता माकुइलशोचित्ल से जीत माँगते थे।","कुलीन लोग गहने, लबादे, यहाँ तक कि ख़ुद को भी दाँव पर लगाते; हारने वाले कुछ लोग ग़ुलाम बन जाते। कहा जाता है कि सम्राट मोक्तेसुमा भी अपने सरदारों का खेल देखते थे।","स्पेनी पादरियों को जुआ और पुराने देवताओं की प्रार्थना पसंद नहीं थी, इसलिए उन्होंने पातोल्ली पर रोक लगाई, चटाइयाँ तोड़ीं और बीन्स जला दीं; इसलिए बहुत कम सेट बचे। फिर भी पत्थर के फ़र्शों और चट्टानों पर खुदे बोर्ड तेओतिहुआकान और माया स्थलों में, और 1977 में हालिस्को की शैल‑नक़्क़ाशियों के बीच मिले।","क्रॉस‑आकार का बोर्ड, जिस पर गोटियाँ चक्कर लगाती हैं, भारत की पचीसी से बहुत मिलता है। 1878 में अंग्रेज़ ई. बी. टायलर ने इसके एशियाई मूल की बात कही; आज ज़्यादातर लोग मानते हैं कि दोनों अलग‑अलग जन्मे।"],"quiz":[["पातोल्ली में पासों की जगह क्या फेंका जाता था?","निशान वाली बीन्स","जानवरों की हड्डियाँ","सीपियाँ","लकड़ी की छड़ें"],["अभिलेखों के अनुसार पातोल्ली पर रोक क्यों लगी?","जुआ और पुराने देवताओं की प्रार्थना","बोर्ड बहुत बड़ा था","बीन्स महँगी थीं","राजा हार गया"],["पातोल्ली का बोर्ड किस खेल से बहुत मिलता है?","पचीसी","गो","चेकर्स","मनकाला"]],"kf":["एक एज़्टेक दौड़ का खेल: निशान लगी पाँच बीन्स फेंककर क्रॉस के आकार के बोर्ड पर गोटियाँ चलाई जाती थीं","जुए और देवताओं की प्रार्थना से जुड़ा होने के कारण स्पेनी पादरियों ने इसे प्रतिबंधित किया","यह भारत के पचीसी से हैरतअंगेज़ रूप से मिलता है, पर माना जाता है कि दोनों अलग-अलग जन्मे"],"more":[{"h":"52 खानों का क्रॉस-रास्ता","p":["पातोल्ली का बोर्ड कपड़े, चटाई या पत्थर के फ़र्श पर बना क्रॉस के आकार का रास्ता है। पुनर्निर्माणों में आम तौर पर चारों भुजाओं में खानों की दो-दो पट्टियाँ होती हैं, जो बीच के चार खानों के साथ 52 बनती हैं।","बावन, एज़्टेक कैलेंडर के एक पूरे चक्र के वर्षों की संख्या भी है; इसलिए कुछ शोधकर्ता बोर्ड में कैलेंडर या बीतते समय की छवि देखते हैं। गोटियों को पूरे रास्ते का चक्कर लगवाया जाता था; जो पहले घर लौटे, वह जीतता।"],"cap":["पातोल्ली का बोर्ड, जैसा अक्सर पुनर्निर्मित किया जाता है: चार भुजाओं में छह-छह खानों की दो पट्टियाँ, और बीच के चार खाने — कुल 52। भुजाओं के सिरों के लाल खाने ख़ास माने जाते हैं"]},{"h":"पाँच बीन्स","p":["पासों की जगह पाँच बीन्स फेंकी जाती थीं, जिनकी एक ओर छेद या निशान होता था; जितने निशान ऊपर आएँ, उतने खाने चलते थे। पाँचों निशान एक साथ 32 में सिर्फ़ एक बार आते हैं।","कहा जाता है कि फेंकने से पहले बीन्स से बात की जाती और खेलों के देवता माकुइलशोचित्ल को पुकारा जाता था। 16वीं सदी के ‘कोडेक्स मालियाबेकियानो’ में देवता की निगरानी में पातोल्ली बोर्ड के इर्द-गिर्द बैठे लोग दिखाए गए हैं।"],"cap":["पाँच बीन्स में से कितनी निशान वाली ओर ऊपर गिरीं (0–5) और कितनी बार (32 में), अगर हर बीन दोनों ओर बराबर गिरे"]},{"h":"पचीसी का हमशक्ल","p":["क्रॉस-आकार के बोर्ड के चारों ओर घूमती गोटियाँ, और फेंकी गई चीज़ों में कितनी ऊपर की ओर गिरीं, उसी के हिसाब से चाल: पातोल्ली और भारत के पचीसी या चौपड़ अचरज भरे ढंग से मिलते हैं। 1878 में ब्रिटिश मानवविज्ञानी टायलर ने कहा कि यह संयोग नहीं, बल्कि इस बात का संकेत है कि खेल एशिया से आया।","पर महासागर पार ऐसी यात्रा का कोई सबूत नहीं मिला। आज ज़्यादातर लोग मानते हैं कि अलग-अलग जगहों के लोग अपने आप एक ही विचारों तक पहुँचे: घूमता हुआ रास्ता और फेंकने की चीज़ें।"],"cap":["भारत में चौपड़ का चित्र (1694–95): गोटियाँ क्रॉस-आकार के बोर्ड का चक्कर लगाती हैं, ठीक पातोल्ली की तरह"]}],"tl":[["तेओतिहुआकान का दौर","पत्थर के फ़र्शों पर क्रॉस-आकार के बोर्ड खोदे गए"],["1519–21","स्पेन ने एज़्टेकों को जीता"],["16वीं सदी","‘कोडेक्स मालियाबेकियानो’ में पातोल्ली और माकुइलशोचित्ल का चित्र"],["लगभग 1577","साहागुन ने ‘फ़्लोरेंटाइन कोडेक्स’ में पातोल्ली दर्ज किया"],["लगभग 1581","दुरान ने प्रार्थनाओं और जुए का वर्णन किया"],["1878","टायलर ने एशियाई उद्गम का मत रखा"],["1977","हालिस्को के शैलचित्रों के बीच एक बोर्ड मिला"]]},"xiangqi":{"title":"शियांगची की नदी और तोप","lead":"बीच में बहती \"नदी\" और कूदकर मारने वाली तोप — चीनी शतरंज ने आज का रूप कब पाया?","s":["शियांगची चीनी शतरंज है, जो 9×10 जाल के बिंदुओं पर खेला जाता है। मोहरे अक्षर लिखी गोल चकतियाँ हैं, जो शतरंज की तरह ख़ानों में नहीं, रेखाओं पर चलते हैं।","एक शुरुआती सुराग़ तांग वंश के मंत्री नीउ सेंगरू (779–847) का विचित्र कथाओं का संग्रह \"श्युआनगुआई लू\" है। एक आदमी के सपने में दिखी नन्ही सेना की कहानी में स्वर्गीय घोड़ा, सेनापति, रथ और पैदल सैनिक आते हैं, और गुलेल‑तोप के संकेत भी हैं। पर बोर्ड और चालें आज जैसी नहीं थीं।","9×10 बोर्ड, नदी और तोप वाला आज का रूप सोंग वंश (960–1279) के अभिलेखों में मिलता है। लुओयांग के एक उत्तरी सोंग मक़बरे से मोहरों का पूरा सेट मिला है।","नदी पर अक्सर \"चू नदी, हान सीमा\" लिखा होता है — तीसरी सदी ई.पू. में श्यांग यू के चू और लिउ बांग के हान के युद्ध की सीमा‑रेखा के नाम पर। सेनापति अपने महल से बाहर नहीं जा सकता, और दोनों सेनापति बीच में कोई मोहरा न हो तो आमने‑सामने नहीं आ सकते।","तोप ठीक एक मोहरे के ऊपर से कूदकर ही मार सकती है। वियतनाम में शियांगची \"कॉ तुओंग\" नाम से लोकप्रिय है, और कोरिया में इससे मिलता‑जुलता जांगी बना। एटलस में आप दोनों खेल सकते हैं।"],"quiz":[["शियांगची के मोहरे कहाँ चलते हैं?","रेखाओं के बिंदुओं पर","ख़ानों के भीतर","एक घेरे के चारों ओर","षट्भुजों पर"],["आज की शियांगची किस वंश के अभिलेखों में मिलती है?","सोंग","हान","मिंग","चिंग"],["तोप कैसे मारती है?","एक मोहरे के ऊपर से कूदकर","सीधा एक क़दम","तिरछे दो क़दम","सिर्फ़ नदी पार करके"]],"kf":["चीनी शतरंज: लिखे हुए अक्षरों वाली गोल गोटियाँ 9 × 10 रेखाओं के जाल के बिंदुओं पर लड़ती हैं","बीच से एक “नदी” गुज़रती है और हर पक्ष के सेनापति का एक “महल” है; हर गोटी का अपना इलाक़ा है","सोंग वंश में इसने आज का रूप लिया और आज भी चीन और वियतनाम में करोड़ों लोग इसे खेलते हैं"],"more":[{"h":"नदी और महलों वाला बोर्ड","p":["हर पक्ष के पास 16 गोटियाँ हैं: एक सेनापति, 2 सलाहकार, 2 हाथी, 2 घोड़े, 2 रथ, 2 तोपें और 5 सैनिक। एक ही भूमिका की कुछ गोटियाँ लाल और काले पक्ष में थोड़े अलग अक्षरों से लिखी जाती हैं।","सेनापति और सलाहकार महल से बाहर नहीं जा सकते, और हाथी नदी पार नहीं कर सकते। सैनिक नदी पार करने तक सिर्फ़ आगे चलते हैं, फिर बग़ल में भी। घोड़ा उस दिशा में ठीक बग़ल में गोटी हो तो छलाँग नहीं लगा सकता। बोर्ड की बनावट ही हर गोटी की भूमिका तय करती है।"],"cap":["शियांगची की शुरुआती जमावट। ऊपर काला, नीचे लाल। 楚河 漢界 अक्षर नदी दिखाते हैं; तिरछी रेखाओं वाले 3 × 3 हिस्से महल हैं"]},{"h":"छलाँग लगाती तोप","p":["तोप आम तौर पर रथ की तरह रेखा पर कितनी भी दूर चलती है। पर मारने के लिए उसे बीच की ठीक एक गोटी — किसी भी रंग की — लाँघनी पड़ती है, जिसे “ओट” कहते हैं।","ओट के इस्तेमाल से ऐसी चालें बनती हैं जो और किसी खेल में नहीं। शुरुआत में तोप को बीच की खड़ी रेखा पर लाना — “केंद्रीय तोप” — आज भी सबसे लोकप्रिय शुरुआतों में से है।"],"cap":["तोप कैसे मारती है: लाल तोप बीच की ठीक एक गोटी — काले घोड़े — को लाँघकर आगे के काले रथ को मारती है"]},{"h":"बाज़ियों के संग्रह और उस्ताद","p":["मिंग वंश में सुंदर बाज़ियों और पहेलियों के कई संग्रह बने। ‘शिचिंग याचू’ (1570) और ‘जूझोंग मी’ (1632) ऐसी क्लासिक किताबें हैं जिनका आज भी अध्ययन होता है।","20वीं सदी में हू रोंगहुआ ने चीन की राष्ट्रीय चैंपियनशिप लगातार दस बार जीती, और 1993 में विश्व शियांगची महासंघ बना, जिससे अंतरराष्ट्रीय प्रतियोगिताएँ शुरू हुईं। चीन और वियतनाम के पार्कों में आज भी रोज़ बोर्ड के चारों ओर दर्शकों का घेरा बनता है।"],"cap":[]}],"tl":[["9वीं सदी","न्यू सेंगरू के ‘शुआनगुआई लू’ में सेनापति, रथ और घोड़े का ज़िक्र"],["सोंग (960–1279)","9 × 10 बोर्ड, नदी और तोप वाला आज का रूप अभिलेखों में दिखता है"],["उत्तरी सोंग","लुओयांग की एक क़ब्र में गोटियों का पूरा सेट रखा गया"],["1570","बाज़ियों का संग्रह ‘शिचिंग याचू’"],["1632","बाज़ियों का संग्रह ‘जूझोंग मी’"],["1960–70 का दशक","हू रोंगहुआ ने लगातार दस राष्ट्रीय ख़िताब जीते"],["1993","विश्व शियांगची महासंघ की स्थापना"]]},"backgammon":{"title":"क्या बैकगैमन 5000 साल पुराना है?","lead":"\"सबसे पुराना बैकगैमन\" कहलाने वाला बोर्ड और खेल के असली पूर्वज — फ़ारसी दरबार से न्यूयॉर्क के क्लबों तक।","s":["ईरान के \"जले हुए शहर\" शहर‑ए‑सोख़्ता से लगभग 5000 साल पुराना बोर्ड, 60 गोटियाँ और पासे मिले, जिसे अक्सर सबसे पुराना बैकगैमन कहा जाता है। पर इसके ख़ाने एक उकेरे गए साँप की कुंडलियों से बने हैं, लगभग बीस — आज के खेल से अलग आकार।","बैकगैमन का संभावित सीधा पूर्वज फ़ारस का \"नर्द\" है, जो तीसरी से छठी सदी के बीच सामने आया। सातवीं‑नौवीं सदी में लिखी एक मध्य‑फ़ारसी कथा कहती है कि मंत्री बोज़ोर्गमेहर ने भारत से आई शतरंज की पहेली सुलझाई और जवाब में नर्द बनाया।","रोम का भी तीन पासों वाला बोर्ड‑खेल था — ताबुला (कहानी 3 में सम्राट ज़ेनो की बदक़िस्मत बाज़ी)। \"टेबल्स\" का यह परिवार पूरे यूरोप में फैला और फ़्रांस के ट्रिक‑ट्रैक जैसे कई रिश्तेदार बने।","\"बैकगैमन\" नाम सत्रहवीं सदी के इंग्लैंड में दिखता है, और 1743 में एडमंड हॉयल ने इसके नियम और रणनीति छापे।","आख़िरी बड़ा आविष्कार, डबलिंग क्यूब, कहते हैं 1920 के दशक में न्यूयॉर्क के क्लबों में जन्मा। बीच खेल में दाँव दुगना करने की सुविधा ने बैकगैमन को \"कब दबाव डालें\" पढ़ने वाला गहरा खेल बना दिया।"],"quiz":[["शहर‑ए‑सोख़्ता का बोर्ड किस आकार का है?","साँप की कुंडलियों से बने ख़ाने","आज के बैकगैमन जैसा","गोल चकती","क्रॉस"],["कथा के अनुसार नर्द किसने बनाया?","मंत्री बोज़ोर्गमेहर","सम्राट ज़ेनो","एडमंड हॉयल","अल्फ़ोंसो दसवें"],["1920 के दशक में न्यूयॉर्क में क्या जन्मा माना जाता है?","डबलिंग क्यूब","दो पासे","24 त्रिकोण","पंद्रह गोटियाँ"]],"kf":["हर पक्ष की पंद्रह गोटियाँ दो पासों से 24 त्रिकोणों पर दौड़ती हैं; जो पहले सब बाहर निकाल दे, वह जीतता है","सीधे पूर्वज फ़ारस का नर्द और रोम का ताबुला — “टेबल्स” परिवार के खेल","दोगुना करने वाले घन और कंप्यूटरों ने 20वीं सदी में इसे नई गहराई दी"],"more":[{"h":"पंद्रह गोटियाँ और 24 त्रिकोण","p":["बोर्ड पर 24 लंबे त्रिकोण (पॉइंट) होते हैं और हर खिलाड़ी के पास 15 गोटियाँ। दो पासे फेंककर हर अंक के लिए एक गोटी, या दोनों अंकों के लिए एक ही गोटी चलाते हैं। जोड़ा आए तो वह अंक चार बार चलते हैं।","विरोधी की अकेली गोटी पर पहुँचें तो उसे “मारकर” बीच की बार पर भेज देते हैं; उसे विरोधी के घर से फिर अंदर आना पड़ता है। अपनी पंद्रहों गोटियाँ घर में आ जाएँ तो उन्हें बोर्ड से बाहर निकालना शुरू करते हैं, और जो पहले पूरा करे, वह जीतता है।"],"cap":["बैकगैमन की शुरुआती जमावट। सफ़ेद 24 से 1 की ओर (घड़ी की उल्टी दिशा में) चलता है; नीचे दाईं ओर के 1–6 उसका घर हैं। काला उल्टी दिशा में चलता है"]},{"h":"जितना पास, उतना आसान निशाना","p":["अकेली गोटी को मारा जा सकता है या नहीं, यह दूरी पर बहुत निर्भर है। छह पॉइंट दूर से 36 में 17 दाँव लगते हैं; सात से सिर्फ़ 6।","ये संख्याएँ जानकर पता चलता है कि कौन-सी गोटी ख़तरे में है। शुरुआत में हर खिलाड़ी को सारी गोटियाँ घर लाकर निकालने के लिए कुल 167 अंक चाहिए; मज़बूत खिलाड़ी यही “पिप काउंट” गिनकर आँकते हैं कि कौन आगे है।"],"cap":["अकेली गोटी को 1–12 पॉइंट की दूरी से मारने वाले दाँव: दो पासों के 36 नतीजों में से कितने (रास्ता खुला हो तो)"]},{"h":"क्लबों से विश्व प्रतियोगिताओं तक","p":["1743 में इंग्लैंड के एडमंड हॉयल ने नियमों और रणनीति की किताब छापी। 19वीं सदी के ब्रिटेन में यह खेल इतना प्यारा था कि फ़र्नीचर पर चित्रित होता था, और 1920 के दशक में न्यूयॉर्क के क्लबों में दोगुना करने वाला घन जन्मा।","1964 में बहामास में विश्व प्रतियोगिता हुई और 1970 के दशक में खेल की धूम मच गई। 1979 में हान्स बर्लिनर के प्रोग्राम ने विश्व विजेता लुइजी विल्ला को हराया, और लगभग 1992 में ख़ुद से खेलकर सीखने वाला टीडी-गैमन सर्वश्रेष्ठ इंसानों के क़रीब पहुँच गया।"],"cap":["बैकगैमन खेलते दो लोगों के चित्र वाली अलमारी (लंदन, 1861), मॉरिस, मार्शल, फ़ॉकनर एंड कंपनी के शुरुआती कामों में से"]}],"tl":[["लगभग 3000 ई.पू.","शहर-ए-सोख़्ता में कुंडली मारे साँप जैसा बोर्ड, गोटियाँ और पासे दफ़नाए गए"],["लगभग तीसरी–छठी सदी","फ़ारस में नर्द प्रकट हुआ"],["1743","हॉयल ने बैकगैमन पर किताब छापी"],["1920 का दशक","न्यूयॉर्क में दोगुना करने वाला घन जन्मा"],["1964","बहामास में विश्व प्रतियोगिता"],["1979","बर्लिनर के प्रोग्राम ने विश्व विजेता को हराया"],["लगभग 1992","ख़ुद से खेलकर सीखने वाला टीडी-गैमन आया"]]},"hex":{"title":"दो बार आविष्कृत हेक्स","lead":"एक डेनिश कवि और एक युवा अमेरिकी प्रतिभा ने एक‑दूसरे से अनजान रहकर एक ही खेल सोचा।","s":["हेक्स में खिलाड़ी बारी‑बारी से षट्भुजों के समचतुर्भुज पर पत्थर रखते हैं; जो अपनी दोनों आमने‑सामने की भुजाएँ जोड़ दे, वह जीतता है। बस इतना ही।","सबसे पहले इसे डेनिश गणितज्ञ और कवि पीट हाइन ने सोचा। 1942 में उन्होंने कोपेनहेगन के नील्स बोर संस्थान में इसे दिखाया; उसी साल 26 दिसंबर को अख़बार \"पोलिटिकन\" ने इसे \"पॉलीगॉन\" नाम से छापा, और यह 50 पन्नों के पैड के रूप में बिका।","1943 में हाइन को डेनमार्क छोड़ना पड़ा और खेल ग़ायब हो गया। कुछ साल बाद, 1948–49 में, प्रिंसटन के स्नातकोत्तर छात्र जॉन नैश ने पूरी तरह अलग से वही खेल सोच लिया; कहते हैं उनके साथी इसे \"नैश\" कहते थे।","1952 में पार्कर ब्रदर्स ने इसे \"हेक्स\" नाम से बेचा, और 1957 में मार्टिन गार्डनर ने साइंटिफ़िक अमेरिकन के अपने स्तंभ में इसे पेश किया, जिससे यह दुनिया भर में जाना गया।","हेक्स कभी बराबरी पर ख़त्म नहीं होता। और नैश ने साबित किया कि पहले खिलाड़ी के पास हमेशा जीत की रणनीति होती है — बिना बताए कि वह क्या है। बड़े बोर्डों पर जीत का वह रास्ता आज भी अज्ञात है।"],"quiz":[["हेक्स में कैसे जीतते हैं?","अपनी दोनों भुजाएँ जोड़कर","सारे पत्थर लेकर","राजा को घेरकर","पाँच एक पंक्ति में"],["डेनिश अख़बार में हाइन के खेल का नाम क्या था?","पॉलीगॉन","नैश","कॉन‑टैक‑टिक्स","ओथेलो"],["नैश ने क्या साबित किया?","पहला खिलाड़ी हमेशा जीत सकता है","दूसरा हमेशा जीतता है","हमेशा बराबरी","जीत की सटीक चालें"]],"kf":["षट्भुज खानों पर बारी-बारी पत्थर रखो; जो अपने रंग की आमने-सामने की दो भुजाएँ जोड़ दे, वह जीते","डेनमार्क में पीट हाइन (1942) और अमेरिका में जॉन नैश (1948–49) ने अलग-अलग आविष्कार किया","बराबरी नहीं होती और पहले खिलाड़ी की जीत सिद्ध है — पर बड़े बोर्डों पर कैसे, यह कोई नहीं जानता"],"more":[{"h":"जोड़ने का खेल","p":["बोर्ड षट्भुज खानों का एक समचतुर्भुज है; आधिकारिक आकार 11 × 11 है। लाल ऊपर और नीचे की भुजाएँ, नीला बाएँ और दाएँ की भुजाएँ सँभालता है, और बारी-बारी एक-एक पत्थर रखते हैं। पत्थर कभी नहीं हिलते और न मारे जाते हैं।","बोर्ड भर जाने पर कोई एक पक्ष ज़रूर जुड़ा होता है। षट्भुज कभी सिर्फ़ कोने से नहीं छूते, इसलिए विरोधी की कतार के बीच से निकल जाना संभव नहीं। 1979 में गणितज्ञ डेविड गेल ने दिखाया कि “बराबरी नहीं” का यह गुण गणित के प्रसिद्ध ब्राउवर स्थिर-बिंदु प्रमेय के बराबर है।"],"cap":["7 × 7 का हेक्स बोर्ड। लाल ऊपर-नीचे जोड़कर, नीला बाएँ-दाएँ जोड़कर जीतता है। सुनहरे किनारे वाले लाल पत्थरों ने ऊपर से नीचे जोड़ दिया है"]},{"h":"पुल और सीढ़ियाँ","p":["मज़बूत खिलाड़ियों का प्रिय औज़ार है पुल। पत्थर ठीक बग़ल में नहीं, एक खाना छोड़कर रखो, तो दोनों के बीच दो साझा ख़ाली खाने बनते हैं। विरोधी एक बंद करे, तो दूसरा ले लो — यानी व्यवहार में वे पहले से जुड़े हैं।","किनारों के पास कई तय आकृतियाँ जानी जाती हैं, जैसे किनारे के साथ-साथ चलकर उस तक पहुँचने वाली पत्थरों की “सीढ़ियाँ”। पहले खिलाड़ी को बहुत ज़्यादा फ़ायदा होने से आम तौर पर अदला-बदली का नियम चलता है: पहली चाल के बाद दूसरा खिलाड़ी वह पत्थर अपना बना सकता है।"],"cap":["“पुल”। दो लाल पत्थर बीच के दो ख़ाली खानों (बिंदीदार घेरे) में से किसी से भी जुड़ सकते हैं। नीला एक ले, तो लाल दूसरा ले लेता है"]},{"h":"गणितज्ञों का खेल","p":["नैश ने “रणनीति चुराने” वाले तर्क से सिद्ध किया कि पहला खिलाड़ी जीतता है: अगर दूसरे के पास जीत की रणनीति होती, तो पहला उसे अपना लेता — यह विरोधाभास है। यह एक अजीब प्रमाण है, जो कोई भी जिताऊ चाल नहीं बताता।","1950 के दशक में सूचना सिद्धांत के जनक क्लॉड शैनन ने बिजली के सर्किट से हेक्स खेलने वाली मशीन बनाई। 2010 के दशक में कंप्यूटरों ने 9 × 9 तक के सारे बोर्ड हल कर दिए, पर आधिकारिक 11 × 11 बोर्ड अब भी अनसुलझा है।"],"cap":[]}],"tl":[["1942","हाइन ने डेनमार्क के अख़बार में ‘पॉलीगॉन’ छापा"],["1948–49","प्रिंसटन में नैश ने वही खेल सोचा"],["1952","पार्कर ब्रदर्स ने इसे ‘हेक्स’ नाम से बेचा"],["1950 का दशक","शैनन ने हेक्स खेलने वाली बिजली की मशीन बनाई"],["1957","गार्डनर ने अपने स्तंभ में परिचय दिया"],["1979","गेल ने स्थिर-बिंदु प्रमेय से संबंध दिखाया"],["2010 का दशक","9 × 9 तक के बोर्ड कंप्यूटर से हल हुए"]]},"foxgeese":{"title":"लोमड़ी, हंस और राजा की चाँदी की गोटियाँ","lead":"एक लोमड़ी, ढेर सारे हंस — एक \"शिकार‑खेल\" का लंबा इतिहास, जिसमें दोनों पक्ष बिल्कुल बराबर नहीं।","s":["लोमड़ी और हंस में अकेली लोमड़ी हंसों के ऊपर से कूदकर उन्हें खाती है, जबकि हंस उसे ऐसे घेरने की कोशिश करते हैं कि वह हिल न सके। दोनों पक्षों के नियम अलग हैं; बोर्ड रेखाओं से जुड़े 33 बिंदुओं वाला क्रॉस है।","एक शुरुआती सुराग़ आइसलैंड की \"ग्रेत्तिर गाथा\" (लगभग 14वीं सदी) में आया \"हालाताफ़्ल\" है। इसका अर्थ है \"पूँछ का बोर्ड\", और पूँछ शायद लोमड़ी की है। संभवतः यह नॉर्डिक ताफ़्ल खेलों की एक शाखा थी।","इंग्लैंड में 15वीं सदी के राजा एडवर्ड चतुर्थ के हिसाब‑खातों में \"सोने की परत चढ़ी चाँदी की दो लोमड़ियाँ और 26 शिकारी कुत्ते\" ख़रीदने का उल्लेख है — दो सेटों की गोटियाँ, जिन्हें तब शायद \"लोमड़ी और शिकारी कुत्ते\" कहा जाता था।","मूल 13 हंसों के साथ लोमड़ी बहुत ताक़तवर थी, इसलिए ज़्यादा हंसों वाले तरीक़े फैले। कहा जाता है कि 19वीं सदी में महारानी विक्टोरिया को यह खेल पसंद था।","वही क्रॉस‑आकार का बोर्ड अकेले खेले जाने वाले पेग सॉलिटेयर में भी इस्तेमाल होता है। नेपाल के बाघ‑चाल जैसे शिकार‑खेल, जिनमें बाघ या भेड़िया शिकार का पीछा करता है, दुनिया भर में हैं। एटलस में आप लोमड़ी और हंस भी खेल सकते हैं और पेग सॉलिटेयर भी।"],"quiz":[["हालाताफ़्ल में \"हाला\" का अर्थ क्या है?","पूँछ","लोमड़ी","राजा","बर्फ़"],["एडवर्ड चतुर्थ के खातों में कौन‑सी गोटियाँ हैं?","चाँदी की लोमड़ियाँ और कुत्ते","सोने के हंस","हाथीदाँत का राजा","लकड़ी के पासे"],["कौन‑सा अकेले का खेल वही क्रॉस बोर्ड इस्तेमाल करता है?","पेग सॉलिटेयर","सुडोकू","ताश का सॉलिटेयर","टैनग्राम"]],"kf":["33 बिंदुओं वाले क्रॉस-आकार के बोर्ड पर एक लोमड़ी 13 (बाद में 17) हंसों से लड़ती है","लोमड़ी कूदकर मारती है; हंस लोमड़ी को ऐसे घेर लें कि वह हिल न सके, तो वे जीतते हैं","वही बोर्ड पेग सॉलिटेयर में भी इस्तेमाल होता है, और ऐसे शिकार के खेल दुनिया भर में हैं"],"more":[{"h":"एक बनाम तेरह","p":["लोमड़ी रेखाओं पर एक क़दम चलती है, और पास के हंस के पीछे का बिंदु ख़ाली हो तो उसे लाँघकर मार देती है; चेकर्स की तरह लगातार कई बार भी कूद सकती है। हंस मार नहीं सकते, और कई रूपों में पीछे भी नहीं हट सकते।","हंसों का लक्ष्य बिना दरार के क़तार बनाकर लोमड़ी को घेरना और उसकी हर चाल छीन लेना है। कहा जाता है कि तेरह हंसों में लोमड़ी बहुत भारी पड़ती है; पीछे न हट सकने वाले सत्रह हंसों के साथ अच्छा खेलें तो हंस जीतते हैं।"],"cap":["लोमड़ी और हंस का बोर्ड: रेखाओं से जुड़े क्रॉस-आकार के 33 बिंदु। तेरह हंस ऊपर खड़े हैं; लोमड़ी (नारंगी) ठीक सामने के हंस (×) को लाँघकर पीछे के ख़ाली बिंदु पर जाकर उसे मार सकती है"]},{"h":"शिकार के खेलों का परिवार","p":["कुछ ताक़तवर गोटियाँ बहुत-सी कमज़ोर गोटियों का पीछा करें — ऐसे शिकार के खेल हर जगह हैं। नेपाल के बाघचाल में 5 × 5 के बोर्ड पर चार बाघ बीस बकरियों का शिकार करते हैं; 2004 में गणना से पता चला कि बिना चूक खेलने पर यह बराबरी है।","19वीं सदी के जर्मनी में लोकप्रिय असाल्टो उसी क्रॉस-बोर्ड पर खेला जाता है: दो अफ़सर बनाम चौबीस सैनिक। यहाँ अफ़सर उस क़िले की रक्षा करते हैं जिस पर सैनिक धावा बोलते हैं।"],"cap":["संख्याओं में शिकार के खेल: बाएँ शिकारी (नारंगी), दाएँ शिकार (सफ़ेद)। ऊपर से: लोमड़ी और हंस (1:13), ज़्यादा हंसों वाला रूप (1:17), नेपाल का बाघचाल (4:20) और असाल्टो (2:24)"]},{"h":"राजा की गोटियों से पेग सॉलिटेयर तक","p":["इंग्लैंड के एडवर्ड चतुर्थ (शासन 1461–83) के हिसाब-किताब में लोमड़ी और शिकारी कुत्तों के खेल के लिए सोने का पानी चढ़ी चाँदी की गोटियाँ ख़रीदने का ज़िक्र है। यह राजाओं और सामंतों का भी मनोरंजन था।","33 छेदों वाला वही क्रॉस-बोर्ड अकेले खेले जाने वाले पेग सॉलिटेयर में भी काम आता है। 1697 की एक फ़्रांसीसी नक़्क़ाशी में एक कुलीन महिला इसे खेलती दिखती है — पेग सॉलिटेयर के सबसे पुराने अभिलेखों में से एक।"],"cap":[]}],"tl":[["लगभग 14वीं सदी","आइसलैंड की ‘ग्रेत्तिर गाथा’ में ‘हालाताफ़्ल’"],["15वीं सदी का अंत","एडवर्ड चतुर्थ ने लोमड़ी और शिकारी कुत्तों की चाँदी की गोटियाँ ख़रीदीं"],["1697","फ़्रांसीसी नक़्क़ाशी में पेग सॉलिटेयर खेलती महिला"],["19वीं सदी","कहा जाता है कि महारानी विक्टोरिया को यह खेल पसंद था"],["19वीं सदी","उसी बोर्ड का असाल्टो जर्मनी में लोकप्रिय हुआ"],["2004","दिखाया गया कि नेपाल का बाघचाल बिना चूक खेलने पर बराबरी है"]]},"latrunculi":{"title":"रोमन सैनिकों की बिसात","lead":"रोमनों का प्यारा “भाड़े के सैनिकों का खेल”। नियमों की कोई किताब नहीं बची — बस कविताएँ, क़िस्से और ज़मीन से निकली बिसातें।","s":["लूडुस लात्रुंकुलोरुम प्राचीन रोम का दो खिलाड़ियों का युद्ध-खेल था। ‘लात्रुंकुली’ का मूल अर्थ भाड़े के सैनिक या लुटेरे था, और गोटियाँ सैनिक मानी जाती थीं।","गोटियाँ खानेदार बिसात पर चलती थीं, और दो दुश्मन गोटियों के बीच फँसी गोटी पकड़ी जाती थी। पहली सदी की कविता ‘लाउस पिसोनिस’ में आगे बढ़ती, पीछे हटती गोटियों और ऐसी घिरी गोटी का वर्णन है जो हिल न सके।","दार्शनिक सेनेका यूलियस कानुस का क़िस्सा सुनाते हैं, जिसे सम्राट कालिगुला ने मौत की सज़ा दी थी। जब सेनानायक उसे लेने आया, कानुस लात्रुंकुली खेल रहा था; उसने गोटियाँ गिनीं और विरोधी से कहा कि उसकी मौत के बाद जीतने का झूठा दावा न करे।","बिसातें पूरे साम्राज्य में मिली हैं। क़िलों और नगरों के पत्थरों पर खुदे जाल लगभग 8 × 8 से 12 × 12 तक के हैं। इंग्लैंड के स्टैनवे की पहली सदी की एक क़ब्र में काँच की गोटियाँ अब भी अपनी बिसात पर सजी थीं।","नियमों की कोई विस्तृत किताब नहीं बची; आज के नियम शोधकर्ताओं के पुनर्निर्माण हैं। एटलस का लात्रुंकुली इन्हीं में से एक पर आधारित है।"],"quiz":[["लात्रुंकुली में गोटी कैसे पकड़ी जाती है?","दो गोटियों के बीच फँसाकर","उसके ऊपर से कूदकर","पासा फेंककर","राजा को घेरकर"],["मृत्युदंड के लिए ले जाने आए तब भी कौन लात्रुंकुली खेल रहा था?","यूलियस कानुस","सीज़र","नीरो","सिसरो"],["स्टैनवे की क़ब्र में बिसात पर क्या बचा था?","काँच की गोटियाँ","सोने के सिक्के","शतरंज के मोहरे","ताश के पत्ते"]],"kf":["प्राचीन रोम का दो खिलाड़ियों का युद्ध-खेल, जिसकी गोटियाँ सैनिक मानी गईं","दो दुश्मनों के बीच फँसी गोटी पकड़ी जाती है; न हिल सकने वाली गोटियों का भी ज़िक्र है","नियमों की किताब नहीं: कविताओं, क़िस्सों और खुदाई में मिली बिसातों से पुनर्निर्माण"],"more":[{"h":"फँसाओ और घेरो","p":["पुनर्निर्माणों का सबसे समृद्ध स्रोत पहली सदी की कविता ‘लाउस पिसोनिस’ है। वह खेल को रणभूमि की तरह दिखाती है: एक गोटी दुश्मन को लुभाने आगे बढ़ती है, दूसरी उसकी पीठ बचाती है, और दो दुश्मनों के बीच फँसी गोटी हार जाती है।","कविता में घिरकर न हिल सकने वाली गोटी की भी बात है, इसलिए कई पुनर्निर्माण फँसाकर पकड़ने के साथ बंद गोटियों के लिए भी नियम रखते हैं। उत्तरी यूरोप के तफ़्ल खेलों में भी ऐसा ही पकड़ना है।"],"cap":["लात्रुंकुली में पकड़ना (पुनर्निर्माण)। बाएँ: नीले तीर की तरह चलने पर सफ़ेद गोटी दो काली के बीच फँसकर पकड़ी जाती है (×)। दाएँ: चारों ओर से बंद सफ़ेद गोटी हिल नहीं सकती"]},{"h":"दोतरफ़ा बिसात","p":["कवि मार्शल (पहली सदी) ने एक उपहार के साथ लिखी कविता में ऐसी बिसात का वर्णन किया जिसकी एक ओर गोटियाँ पासों से चलती हैं और दूसरी ओर दो रंगों के सैनिक लड़ते हैं — एक ही तख़्ते पर क़िस्मत का खेल और दिमाग़ का खेल।","पासों वाली ओर ‘बारह रेखाएँ’ नाम का दौड़ का खेल माना जाता है, जो ताबुला और बैकगैमन का पूर्वज है। संग्रहालय के संग्रह का पासा-बुर्ज (पिर्गुस) भी रोमनों का औज़ार था।"],"cap":["मार्शल की दोतरफ़ा बिसात की कल्पना: एक ओर पासों से बारह रेखाओं की दौड़, दूसरी ओर सैनिकों के खेल का जाल"]},{"h":"ज़मीन से निकली बिसातें","p":["रोमन सैनिक खेलने के लिए अपने क़िलों के पत्थरों और फ़र्शों पर जाल खोदते थे। खुदी बिसातें ब्रिटेन में हैड्रियन की दीवार के पास और जर्मनी, स्पेन व उत्तर अफ़्रीका में मिली हैं।","स्टैनवे की क़ब्र (पहली सदी के मध्य) में लकड़ी की बिसात सड़ चुकी थी, पर उस पर रखी सफ़ेद और नीली काँच की गोटियाँ अपनी जगह थीं, मानो खेल बीच में रुका हो। मालिक शायद वैद्य था: उनके साथ चिकित्सा के औज़ार भी दफ़न थे।"],"cap":["पासा-बुर्ज (पिर्गुस)। बेईमानी रोकने के लिए रोमन ऐसे बुर्जों से पासे फेंकते थे"]}],"tl":[["पहली सदी ई.पू.","वार्रो ने लात्रुंकुली का नाम लिखा"],["पहली सदी ई.पू. का अंत","ओविड ने प्रेम-कविता में इस खेल का ज़िक्र किया"],["पहली सदी","‘लाउस पिसोनिस’ ने कविता में खेल का वर्णन किया"],["पहली सदी का मध्य","स्टैनवे में गोटियों सहित बिसात दफ़नाई गई"],["पहली सदी","सेनेका ने यूलियस कानुस का क़िस्सा सुनाया"],["पहली सदी का अंत","मार्शल ने दोतरफ़ा बिसात पर लिखा"],["1994","शेडलर ने नियमों का पुनर्निर्माण प्रकाशित किया"]]},"amazons":{"title":"वह खेल जो अपनी ही बिसात जलाता है","lead":"1988 में अर्जेंटीना में जन्मा ‘अमेज़न्स’ शतरंज की रानी की चाल और गो के इलाक़ा गिनने को एक साथ जोड़ता है।","s":["अमेज़न्स 10 × 10 बिसात पर दो खिलाड़ियों का खेल है, जिसमें हर पक्ष के चार ‘अमेज़न’ होते हैं। इसे 1988 में अर्जेंटीना के वाल्टर ज़ाम्काउस्कास ने बनाया।","हर चाल के दो हिस्से होते हैं। पहले अमेज़न शतरंज की रानी की तरह आड़ी, खड़ी या तिरछी सीधी रेखा में चलती है; फिर जहाँ पहुँची, वहाँ से उसी तरह एक तीर छोड़ती है। जिस खाने में तीर लगे, उसे फिर कोई पार नहीं कर सकता।","हर चाल एक और खाना भर देती है, और जो खिलाड़ी आगे न चल सके, वह हारता है। बराबरी नहीं होती।","आख़िर में तीर बिसात को अलग-अलग कमरों में बाँट देते हैं। तब जिसके अपने ख़ाली खाने ज़्यादा हों, वह जीतता है, इसलिए गो की तरह इलाक़ा गिनकर स्थिति आँकी जाती है।","सिर्फ़ पहली चाल के ही 2,000 से ज़्यादा विकल्प हैं, जिससे यह कंप्यूटरों के लिए भी कठिन है। गणितज्ञ इसका अध्ययन करते हैं, और यह कंप्यूटर प्रतियोगिताओं का एक मुक़ाबला है।"],"quiz":[["अमेज़न्स किस देश में जन्मा?","अर्जेंटीना","ब्राज़ील","स्पेन","मेक्सिको"],["जिस खाने में तीर छोड़ा जाए, उसका क्या होता है?","उसे फिर कोई पार नहीं कर सकता","अगली बारी में मिट जाता है","विरोधी की गोटी बन जाता है","अंक मिलता है"],["अमेज़न्स में कौन हारता है?","जो पहले न चल सके","जो पहले गोटी गँवाए","जो पहले इलाक़ा बनाए","जिसका समय ख़त्म हो"]],"kf":["1988 में अर्जेंटीना में जन्मा, 10 × 10 बिसात पर दो खिलाड़ियों का खेल","अमेज़न रानी की तरह चलती है और पहुँचने की जगह से तीर छोड़कर एक खाना जलाती है","जो न चल सके वह हारता है; अंत में गो की तरह इलाक़ा गिना जाता है"],"more":[{"h":"चलो, फिर तीर छोड़ो","p":["अमेज़न कितने भी खाने चल सकती है, बशर्ते किसी गोटी या तीर को न लाँघे। जहाँ पहुँचे, वहाँ से वह फिर रानी की चाल से तीर छोड़ती है — अभी छोड़े हुए खाने में भी।","कुछ भी पकड़ा नहीं जाता। इसके बजाय हर चाल बिसात का एक खाना बंद करती है और विरोधी के रास्ते रोकती है: हमला और बचाव एक ही तीर से तय होते हैं।"],"cap":["अमेज़न्स की एक चाल। सफ़ेद अमेज़न रानी की तरह चलती है (नीला), फिर पहुँचने की जगह से उसी तरह तीर छोड़ती है (लाल)। तीर वाला खाना हमेशा के लिए बंद"]},{"h":"कमरों में बँटी बिसात","p":["खेल आगे बढ़ने पर तीर बिसात को कमरों में बाँट देते हैं। अगर किसी कमरे में एक ही खिलाड़ी की अमेज़न हों, तो उसके ख़ाली खाने सिर्फ़ उसी के होते हैं, जिन्हें वह एक-एक चाल में ख़र्च करता है।","तब खेल गिनती बन जाता है: जिसके पास काम के खाने ज़्यादा हों, वह ज़्यादा देर चल सकता है। यह संयोजक खेल-सिद्धांत से ख़ूब मेल खाता है, और एल्विन बर्लेकैंप आदि ने अमेज़न्स के अंत का बारीकी से अध्ययन किया।"],"cap":["अंत की स्थिति (चित्रण)। जले खानों की दीवारें बिसात को चार कमरों में बाँटती हैं: हरे सिर्फ़ सफ़ेद के, नीले सिर्फ़ काले के काम के। जिसके ख़ाली खाने ज़्यादा, वह देर तक चल सकता है"]},{"h":"पत्रिका में जन्मा, कंप्यूटरों में मुक़ाबला","p":["कहा जाता है कि यह खेल पहली बार अर्जेंटीना की एक पहेली-पत्रिका में छपा। नियम छोटे हैं और शतरंज की बिसात व कुछ गोटियाँ काफ़ी हैं, इसलिए इंटरनेट के ज़रिए यह दुनिया भर में फैल गया।","2,000 से ज़्यादा संभावित पहली चालों के साथ, शुरुआत में गो की तरह पूरी बिसात की समझ चाहिए। 2000 के दशक से यह कंप्यूटर प्रतियोगिताओं का मुक़ाबला है, जहाँ प्रोग्राम आपस में भिड़ते हैं।"],"cap":[]}],"tl":[["1988","वाल्टर ज़ाम्काउस्कास ने अमेज़न्स बनाया"],["1990 का दशक","इंटरनेट के ज़रिए दुनिया भर में फैला"],["2000","बर्लेकैंप ने इसके अंत पर गणितीय काम प्रकाशित किया"],["2000 का दशक","कंप्यूटर ओलंपियाड का मुक़ाबला बना"]]},"loa":{"game":"लाइन्स ऑफ़ एक्शन","title":"जितना गिनो, उतना चलो","lead":"लाइन्स ऑफ़ एक्शन 1969 में सिड सैक्सन की एक किताब से दुनिया के सामने आया। जीत गोटियाँ मारने से नहीं, बल्कि अपनी सारी गोटियों को एक समूह में जोड़ने से मिलती है।","s":["लाइन्स ऑफ़ एक्शन (LOA) 8 × 8 बोर्ड पर दो खिलाड़ियों का खेल है, हर पक्ष के पास बारह गोटियाँ। इसे क्लॉड सूसी ने बनाया, और 1969 में खेल-संग्रहकर्ता सिड सैक्सन की किताब A Gamut of Games में इसका परिचय दिया गया।","गोटी सीधी रेखा में चलती है — आड़ी, खड़ी या तिरछी। वह कितना चलेगी, यह ठीक उस रेखा पर मौजूद गोटियों (अपनी और विरोधी, दोनों) की संख्या के बराबर होता है। हर चाल ये गिनतियाँ बदल देती है, और साथ में दूरियाँ भी।","अपनी गोटियों के ऊपर से कूदा जा सकता है, पर विरोधी की गोटियों के ऊपर से कभी नहीं। विरोधी की गोटी वाले खाने पर रुकने से वह गोटी मार दी जाती है।","लक्ष्य है अपनी सारी गोटियों को एक ही समूह में जोड़ना, जहाँ वे आड़ी, खड़ी या तिरछी दिशा में एक-दूसरे को छूती हों। गोटियाँ मारने से विरोधी की सेना छोटी होती है, और कभी-कभी इससे उसे जुड़ने में मदद ही मिल जाती है — एक अनोखा मोड़।","नियम छोटे हैं, पर आगे की चालें सोचना कठिन है, इसलिए यह खेल लंबे समय से गेम-AI के शोध में इस्तेमाल होता आया है। नीदरलैंड्स की मास्ट्रिख्ट यूनिवर्सिटी के प्रोग्राम कई बार कंप्यूटर प्रतियोगिताएँ जीत चुके हैं।"],"quiz":[["गोटी कितने खाने चलेगी, यह किससे तय होता है?","उस रेखा पर गोटियों की संख्या से","पासे के अंक से","अब तक मारी गई गोटियों की संख्या से","हमेशा तीन खाने"],["LOA में जीत कैसे होती है?","अपनी सारी गोटियों को एक समूह में जोड़कर","विरोधी की सारी गोटियाँ मारकर","बोर्ड के दूसरे किनारे तक पहुँचकर","विरोधी के राजा को मारकर"],["1969 की किताब में LOA का परिचय किसने दिया?","सिड सैक्सन","मार्टिन गार्डनर","एडमंड हॉयल","एच. जे. आर. मरे"]],"kf":["8 × 8 बोर्ड पर बारह-बारह गोटियों वाला दो खिलाड़ियों का खेल; क्लॉड सूसी ने बनाया, 1969 में सिड सैक्सन की किताब में परिचय","गोटी ठीक उतने खाने चलती है जितनी गोटियाँ उसकी रेखा पर हैं; अपनी गोटियाँ लाँघ सकती है, विरोधी की कभी नहीं","सबसे ज़्यादा गोटियाँ मारने वाला नहीं, बल्कि सबसे पहले सारी गोटियाँ जोड़ने वाला जीतता है"],"more":[{"h":"गिनो, फिर चलो","p":["मान लीजिए किसी गोटी से गुज़रने वाली आड़ी पंक्ति पर तीन गोटियाँ हैं; तब वह गोटी उस पंक्ति में ठीक तीन खाने चलेगी — न ज़्यादा, न कम। रास्ते में वह अपनी गोटियाँ लाँघ सकती है, पर अगर बीच में विरोधी की गोटी हो तो उस दिशा में नहीं जा सकती।","हर गोटी चार रेखाओं पर होती है — एक आड़ी, एक खड़ी और दो तिरछी — और हर रेखा की अपनी गिनती होती है। एक गोटी चलते ही आसपास की कई रेखाओं की गिनती बदल जाती है, इसलिए बोर्ड की “दूरियाँ” हर चाल में नए सिरे से फेंटी जाती हैं। यही LOA को इतना कठिन बनाता है।"],"cap":["तीरों के शुरू वाली काली गोटी कहाँ जा सकती है। आड़ी पंक्ति में 3 गोटियाँ हैं, इसलिए वह 3 खाने चलती है (अपनी गोटी लाँघना ठीक है); खड़े स्तंभ में 2 हैं, इसलिए 2 खाने चलकर सफ़ेद गोटी मारती है। तिरछी रेखा पर भी 3 हैं, पर बीच में सफ़ेद गोटी रास्ता रोकती है (×)"]},{"h":"एक समूह जीतता है","p":["गोटियाँ तब जुड़ी मानी जाती हैं जब वे आड़ी, खड़ी या तिरछी दिशा में एक-दूसरे को छूती हों। जिसके पास केवल एक गोटी बची हो, वह भी “जुड़ा हुआ” है, इसलिए ज़रूरत से ज़्यादा गोटियाँ मारना विरोधी को जीत भी दिला सकता है।","अगर एक ही चाल से दोनों पक्ष एक साथ जुड़ जाएँ, तो क्या होगा — यह संस्करण और प्रतियोगिता पर निर्भर करता है। सैक्सन की किताब के पहले संस्करण में इसे बराबरी माना गया, बाद के संस्करण में चाल चलने वाले की जीत, और आज ज़्यादातर प्रतियोगिताएँ इसे बराबरी गिनती हैं। इस एटलस के LOA में चाल चलने वाला जीतता है।"],"cap":["जीत की स्थिति। सफ़ेद गोटियाँ (सुनहरी किनारी) तिरछी दिशा समेत एक-दूसरे को छूती हैं और एक समूह बनाती हैं। काली गोटियाँ अभी तीन हिस्सों में बँटी हैं (बिंदीदार)"]},{"h":"कंप्यूटरों की होड़ का खेल","p":["छोटा बोर्ड, छोटे नियम और गहरा खेल — इसी कारण LOA गेम-AI की परीक्षा-भूमि बन गया। मास्ट्रिख्ट यूनिवर्सिटी के मार्क विनांड्स का बनाया प्रोग्राम MIA 2003, 2004, 2006 और 2009 में कंप्यूटर ओलंपियाड जीता, और उनका काम 2004 के उनके पीएचडी शोध-प्रबंध Informed Search in Complex Games में संकलित है।","2008 में विनांड्स ने छोटे 6 × 6 बोर्ड पर LOA को हल किया और दिखाया कि सर्वश्रेष्ठ खेल में पहला खिलाड़ी (काला) जीतता है। माना जाता है कि पूरा 8 × 8 खेल अब तक हल नहीं हुआ है। इंसान भी हर साल माइंड स्पोर्ट्स ओलंपियाड में होने वाली विश्व चैंपियनशिप में भिड़ते हैं।"],"cap":[]}],"tl":[["लगभग 1960","कहा जाता है कि क्लॉड सूसी ने LOA बनाया"],["1969","सिड सैक्सन की A Gamut of Games में परिचय"],["2003","विनांड्स का MIA कंप्यूटर ओलंपियाड जीतता है (फिर 2004, 2006 और 2009 में भी)"],["2004","विनांड्स का पीएचडी शोध-प्रबंध Informed Search in Complex Games"],["2008","6 × 6 LOA हल: पहला खिलाड़ी जीतता है"]]}};
